  function normalizeModalItems(items) {
    return (items || [])
      .map(item =>
        String(item || '')
          .replace(/activeChar\.[^,，\s]+/g, '当前角色信息')
          .replace(/sd\.[^,，\s]+/g, '世界状态')
          .replace(/WORLD_MAP_TREE/g, '地图节点')
          .replace(/travel[\s_]?request/gi, '出行安排')
          .replace(/player_action/gi, '玩家行动')
          .replace(/settle_result/gi, '结算结果')

          .replace(/request 变量/gi, '当前安排')
          .replace(/展示/g, '查看')
          .replace(/显示/g, '查看')
          .replace(/整理/g, '收纳')
          .replace(/统一管理/g, '集中查看')
          .replace(/写入/g, '生成')
          .replace(/跳转/g, '前往')
          .replace(/承接/g, '查看')
          .replace(/字段/g, '信息')
          .replace(/变量/g, '内容')
          .replace(/用于显示/g, '展示')
          .replace(/进入这里/g, '收纳于此')
          .replace(/可作为/g, '可视作')
          .replace(/预留/g, '')
          .replace(/后续/g, '')
          .replace(/运行时/g, '')
          .replace(/\(\)/g, '')
          .replace(/\s{2,}/g, ' ')
          .trim(),
      )
      .filter(Boolean);
  }

  function renderGenericModalBody(config) {
    const focusItems = normalizeModalItems(
      config.highlights && config.highlights.length ? config.highlights : config.duties,
    ).slice(0, 6);
    const actionItems = normalizeModalItems(config.actions).slice(0, 6);
    const renderPills = (items, fallback, mode = '') => {
      const source = items.length ? items : [fallback];
      return `<div class="status-tag-rack">${source.map(item => `<span class="status-pill ${mode}">${item}</span>`).join('')}</div>`;
    };
    return `
        <div class="modal-block">
          <div class="modal-block-title">当前要点</div>
          ${renderPills(focusItems, '当前暂无额外要点。')}
        </div>
        <div class="modal-block">
          <div class="modal-block-title">可做事项</div>
          ${renderPills(actionItems, '暂时没有额外操作。', 'live')}
        </div>
      `;
  }

  function makeRadarSvg(labels, values, realValues = null, accent = 'cyan') {
    const size = 220;
    const cx = 110;
    const cy = 110;
    const radius = 70;
    const levels = 4;
    const angleStep = (Math.PI * 2) / labels.length;

    const point = (index, ratio) => {
      const angle = -Math.PI / 2 + angleStep * index;
      return {
        x: cx + Math.cos(angle) * radius * ratio,
        y: cy + Math.sin(angle) * radius * ratio,
      };
    };

    let grids = '';
    for (let level = 1; level <= levels; level++) {
      const ratio = level / levels;
      const pts = labels
        .map((_, idx) => {
          const p = point(idx, ratio);
          return `${p.x},${p.y}`;
        })
        .join(' ');
      grids += `<polygon class="radar-grid-line" points="${pts}"></polygon>`;
    }

    const axes = labels
      .map((_, idx) => {
        const p = point(idx, 1);
        return `<line class="radar-axis-line" x1="${cx}" y1="${cy}" x2="${p.x}" y2="${p.y}"></line>`;
      })
      .join('');

    const shapePoints = values
      .map((value, idx) => {
        const p = point(idx, Math.max(0.08, Math.min(1, value / 100)));
        return `${p.x},${p.y}`;
      })
      .join(' ');

    const labelTexts = labels
      .map((label, idx) => {
        const p = point(idx, 1.22);
        let anchor = 'middle';
        if (p.x < cx - 10) anchor = 'end';
        else if (p.x > cx + 10) anchor = 'start';
        return `<text x="${p.x}" y="${p.y}" text-anchor="${anchor}" dominant-baseline="middle" class="radar-label">${label}</text>`;
      })
      .join('');

    const legend = labels
      .map(
        (label, idx) => `
        <div class="legend-chip">
          <b>${label}</b>
          <span>${realValues ? realValues[idx] : values[idx]}</span>
        </div>
      `,
      )
      .join('');

    return `
        <div class="radar-shell">
          <div class="radar-visual">
            <svg class="radar-svg" viewBox="0 0 ${size} ${size}">
              ${grids}
              ${axes}
              <polygon class="radar-data-shape ${accent === 'gold' ? 'gold' : ''}" points="${shapePoints}"></polygon>
              ${labelTexts}
            </svg>
          </div>
          <div class="radar-legend">${legend}</div>
        </div>
      `;
  }

  function 构建星图详情雷达图HTML(指标列表 = [], 选项 = {}) {
    const 安全指标 = (Array.isArray(指标列表) ? 指标列表 : [])
      .map(指标 => ({
        标签: toText(指标 && 指标.标签, '指标'),
        数值: Math.max(0, Math.min(100, toNumber(指标 && 指标.数值, 0))),
        文本: toText(指标 && 指标.文本, ''),
      }))
      .slice(0, 5);
    if (!安全指标.length) return '';
    const 尺寸 = 220;
    const 中心 = 110;
    const 半径 = 64;
    const 层数 = 4;
    const 角步长 = (Math.PI * 2) / 安全指标.length;
    const 取点 = (索引, 比例) => {
      const 角度 = -Math.PI / 2 + 角步长 * 索引;
      return {
        x: 中心 + Math.cos(角度) * 半径 * 比例,
        y: 中心 + Math.sin(角度) * 半径 * 比例,
      };
    };
    let 网格 = '';
    for (let 层 = 1; 层 <= 层数; 层++) {
      const 比例 = 层 / 层数;
      网格 += `<polygon class="location-radar-grid-line" points="${安全指标
        .map((_, 索引) => {
          const 点 = 取点(索引, 比例);
          return `${点.x},${点.y}`;
        })
        .join(' ')}"></polygon>`;
    }
    const 轴线 = 安全指标
      .map((_, 索引) => {
        const 点 = 取点(索引, 1);
        return `<line class="location-radar-axis-line" x1="${中心}" y1="${中心}" x2="${点.x}" y2="${点.y}"></line>`;
      })
      .join('');
    const 形状点 = 安全指标
      .map((指标, 索引) => {
        const 点 = 取点(索引, Math.max(0.08, 指标.数值 / 100));
        return `${点.x},${点.y}`;
      })
      .join(' ');
    const 标签文本 = 安全指标
      .map((指标, 索引) => {
        const 点 = 取点(索引, 1.28);
        let 对齐 = 'middle';
        if (点.x < 中心 - 10) 对齐 = 'end';
        else if (点.x > 中心 + 10) 对齐 = 'start';
        return `<text x="${点.x}" y="${点.y}" text-anchor="${对齐}" dominant-baseline="middle" class="location-radar-label"><tspan>${htmlEscape(指标.标签)}</tspan><tspan dx="4">${htmlEscape(String(指标.数值))}</tspan></text>`;
      })
      .join('');
    const 摘要列表 = Array.isArray(选项 && 选项.摘要列表)
      ? 选项.摘要列表
          .map(摘要 => ({
            标签: toText(摘要 && 摘要.标签, ''),
            文本: toText(摘要 && 摘要.文本, ''),
          }))
          .filter(摘要 => 摘要.标签 || 摘要.文本)
      : 安全指标.map(指标 => ({
          标签: 指标.标签,
          文本: 指标.文本 || String(指标.数值),
        }));
    const 指标行 = 摘要列表
      .map(
        摘要 => `
          <span>
            <b>${htmlEscape(摘要.标签)}</b>
            <em>${htmlEscape(摘要.文本)}</em>
          </span>
        `,
      )
      .join('');
    const 类名 = toText(选项 && 选项.类名, '');
    return `
      <div class="location-radar-compact ${escapeHtmlAttr(类名)}">
        <div class="location-radar-canvas">
          <svg class="location-radar-svg" viewBox="0 0 ${尺寸} ${尺寸}">
            ${网格}
            ${轴线}
            <polygon class="location-radar-data-shape" points="${形状点}"></polygon>
            ${标签文本}
          </svg>
        </div>
        <div class="location-radar-metrics">${指标行}</div>
      </div>
    `;
  }

  function 构建详情项值HTML(条目) {
    if (条目 && 条目.值Html) return 条目.值Html;
    const 路径 = normalizeEditorPath(条目 && (条目.path || 条目.路径));
    const 当前值 = 条目 && 条目.value !== undefined && 条目.value !== null ? 条目.value : '';
    if (!路径.length) return 当前值;
    return makeInlineEditableValue(条目 && 条目.displayText !== undefined ? 条目.displayText : 当前值, {
      path: 路径,
      kind: 条目 && (条目.kind || 条目.类型) ? 条目.kind || 条目.类型 : 'string',
      rawValue: 条目 && (条目.rawValue !== undefined || 条目.原始值 !== undefined) ? 条目.rawValue ?? 条目.原始值 : 当前值,
      multiline: !!(条目 && 条目.multiline),
      提示文本: 条目 && 条目.提示文本,
      editorMeta: 条目 && (条目.editorMeta || 条目.编辑元数据),
    });
  }

  const 空状态文本集合 = new Set([
    '',
    '-',
    '--',
    '—',
    '无',
    '空',
    '空槽',
    '暂无',
    '未知',
    '未加入',
    '未收录',
    '未装载',
    '未装备',
    '未部署',
    '未记录',
    '未激活',
    '待接入',
    '待装配',
    '锁定',
    '暂无推进建议',
  ]);

  function 读取空状态判定文本(值) {
    return toText(值, '')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&')
      .replace(/\s+/g, '')
      .trim();
  }

  function 是空状态值(值) {
    const 文本 = 读取空状态判定文本(值);
    if (空状态文本集合.has(文本)) return true;
    const 片段列表 = 文本.split(/[\/／|｜、,，]+/).filter(Boolean);
    return 片段列表.length > 0 && 片段列表.every(片段 => 空状态文本集合.has(片段));
  }

  function makeTileGrid(items, className = '') {
    const tileItems = Array.isArray(items) ? items : [];
    const compactIntelGrid =
      tileItems.length === 2 && tileItems.every(item => ['线索', '影响'].includes(toText(item && item.label, '')));
    const 紧凑情报网格类 = compactIntelGrid ? ' archive-tile-grid--compact-intel' : '';
    const 紧凑情报格类 = compactIntelGrid ? ' archive-tile--compact-intel' : '';
    const 紧凑情报值类 = compactIntelGrid ? ' class="archive-tile-value--compact-intel"' : '';
    return `
      <div class="archive-tile-grid ${className}${紧凑情报网格类}">
          ${tileItems
            .map(
              item => {
                const 悬浮Html = item && item.悬浮Html ? toText(item.悬浮Html, '') : '';
                const 悬浮类 = 悬浮Html ? ' archive-tile--has-hover' : '';
                const 标题属性 = !悬浮Html && item && item.提示文本 ? ` title="${escapeHtmlAttr(item.提示文本)}"` : '';
                const 聚焦属性 = 悬浮Html ? ' tabindex="0"' : '';
                return `
            <div class="archive-tile${紧凑情报格类}${悬浮类}"${标题属性}${聚焦属性}>
              <b>${item.label}</b>
              <span${紧凑情报值类}>${构建详情项值HTML(item)}</span>
              ${悬浮Html}
            </div>
          `;
              },
            )
            .join('')}
        </div>
      `;
  }

  function escapeHtmlAttr(value) {
    return String(value ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function makeInteractiveTileGrid(items, className = '') {
    return `
        <div class="archive-tile-grid ${className}">
          ${(items || [])
            .map(
              item => {
                const 悬浮Html = item && item.悬浮Html ? toText(item.悬浮Html, '') : '';
                const 悬浮类 = 悬浮Html ? ' archive-tile--has-hover' : '';
                const 标题属性 = !悬浮Html && item && item.提示文本 ? ` title="${escapeHtmlAttr(item.提示文本)}"` : '';
                const 聚焦属性 = 悬浮Html ? ' tabindex="0"' : '';
                return `
            <div class="archive-tile ${item.className || ''}${悬浮类} ${item.preview ? 'clickable' : ''}"${item.preview ? ` data-preview="${escapeHtmlAttr(item.preview)}"` : ''}${标题属性}${聚焦属性}>
              <b>${item.label}</b>
              <span>${构建详情项值HTML(item)}</span>
              ${悬浮Html}
            </div>
          `;
              },
            )
            .join('')}
        </div>
      `;
  }

  function makeTagCloud(items, className = '') {
    return `
        <div class="tag-cloud ${className}">
          ${(items || []).map(item => `<span class="tag-chip ${item.className || ''}">${item.text}</span>`).join('')}
        </div>
      `;
  }

  function makeWalletStrip(items) {
    return `
        <div class="wallet-strip wallet-data-ribbon">
          ${(items || [])
            .map(
              item => `
            <div class="wallet-chip wallet-data-chip ${item.className || ''}" data-wallet-key="${escapeHtmlAttr(toText(item.key || item.label, ''))}">
              <b>${item.label}</b>
              <span>${构建详情项值HTML(item)}</span>
            </div>
          `,
            )
            .join('')}
        </div>
      `;
  }

  function makeFigureBoard(coreLabel, slots) {
    return `
        <div class="figure-board">
          <div class="figure-core">${coreLabel}</div>
          ${(slots || [])
            .map(
              slot => `
            <div class="figure-slot ${slot.className || ''}" style="left:${slot.x}%;top:${slot.y}%">${slot.label}</div>
          `,
            )
            .join('')}
        </div>
      `;
  }

  function makeInteractiveFigureBoard(coreLabel, slots, core = {}) {
    return `
        <div class="figure-board">
          <div class="figure-core ${core.preview ? 'clickable' : ''}"${core.preview ? ` data-preview="${escapeHtmlAttr(core.preview)}"` : ''}>${coreLabel}</div>
          ${(slots || [])
            .map(
              slot => `
            <div class="figure-slot ${slot.className || ''} ${slot.preview ? 'clickable' : ''}"${slot.preview ? ` data-preview="${escapeHtmlAttr(slot.preview)}"` : ''} style="left:${slot.x}%;top:${slot.y}%">${slot.label}</div>
          `,
            )
            .join('')}
        </div>
      `;
  }

  function summarizeArmoryValue(value) {
    if (value === undefined || value === null || value === '') return '无';
    if (Array.isArray(value))
      return (
        value
          .map(item => summarizeArmoryValue(item))
          .filter(Boolean)
          .slice(0, 4)
          .join(' / ') || '无'
      );
    if (typeof value === 'object') {
      const named = value.name || value['名称'] || value.title || value['标题'];
      if (named) return String(named);
      return (
        Object.entries(value)
          .filter(([, v]) => v !== undefined && v !== null && v !== '' && typeof v !== 'object')
          .slice(0, 4)
          .map(([k, v]) => `${k}:${v}`)
          .join(' / ') || '无'
      );
    }
    return String(value);
  }

  function buildStatsBonusItems(statsBonus, options = {}) {
    const bonus = statsBonus && typeof statsBonus === 'object' ? statsBonus : {};
    const normalizeBonusValue = value => {
      const text = String(value ?? '').trim();
      const 百分比匹配 = text.match(/^([+-]?\d+(?:\.\d+)?)%$/);
      if (百分比匹配) {
        if (options.percentAsLevel) {
          const 等级 = Number(百分比匹配[1]) / 10;
          const 文本 = Number.isInteger(等级) ? String(等级) : String(Number(等级.toFixed(2)));
          return `${等级 >= 0 ? '+' : ''}${文本}级`;
        }
        return /^[+-]/.test(text) ? text : `+${text}`;
      }
      const numeric = toNumber(value, 0);
      if (numeric > 0) return Math.floor(numeric);
      if (numeric < 0) return Math.ceil(numeric);
      return 0;
    };
    const 格式化加成值 = (原始加成值, 标签) => {
      const 规范值 = normalizeBonusValue(原始加成值);
      if (typeof 规范值 === 'string') return { value: 规范值 };
      return {
        value: 格式化属性短数字(规范值),
        值Html: 构建属性数值Html(标签, 规范值),
        提示文本: `${标签}：${格式化属性完整数字(规范值)}`,
      };
    };
    const items = [];
    if (options.includeLvEquiv && toNumber(bonus.等效等级, 0) > 0)
      items.push({ label: '等效等级', value: String(toNumber(bonus.等效等级, 0)) });
    items.push(
      { label: '体力加成', ...格式化加成值(bonus.体力上限, '体力加成') },
      { label: '魂力加成', ...格式化加成值(bonus.魂力上限, '魂力加成') },
      { label: '精神加成', ...格式化加成值(bonus.精神力上限, '精神加成') },
      { label: '力量加成', ...格式化加成值(bonus.力量, '力量加成') },
      { label: '防御加成', ...格式化加成值(bonus.防御, '防御加成') },
      { label: '敏捷加成', ...格式化加成值(bonus.敏捷, '敏捷加成') },
    );
    return items;
  }

  function buildEditableStatBonusItems(basePath = [], statsBonus = {}, options = {}) {
    const path = Array.isArray(basePath) ? basePath : [];
    const bonus = statsBonus && typeof statsBonus === 'object' ? statsBonus : {};
    const includeSoulPower = options.includeSoulPower !== false;
    const makeBonusValue = field => {
      const 原始值 = bonus[field];
      const 百分比文本 = /^[+-]?\d+(?:\.\d+)?%$/.test(String(原始值 ?? '').trim()) ? String(原始值 ?? '').trim() : '';
      const 数值 = toNumber(原始值, 0);
      const 写入值 = 百分比文本 || (数值 > 0 ? Math.floor(数值) : 数值 < 0 ? Math.ceil(数值) : 0);
      const 显示文本 = 百分比文本 || 格式化属性短数字(写入值);
      return path.length
        ? makeInlineEditableValue(显示文本, {
            path: [...path, field],
            kind: 百分比文本 ? 'string' : 'number',
            rawValue: 写入值,
            提示文本: 百分比文本 || `${field}：${格式化属性完整数字(写入值)}`,
            editorMeta: 百分比文本 ? undefined : { min: 0, integer: true, hint: '最小 0 · 整数' },
          })
        : 百分比文本
          ? htmlEscape(百分比文本)
          : 构建属性数值Html(field, 写入值);
    };
    return [
      { label: '体力加成', value: makeBonusValue('体力上限') },
      ...(includeSoulPower ? [{ label: '魂力加成', value: makeBonusValue('魂力上限') }] : []),
      { label: '精神加成', value: makeBonusValue('精神力上限') },
      { label: '力量加成', value: makeBonusValue('力量') },
      { label: '防御加成', value: makeBonusValue('防御') },
      { label: '敏捷加成', value: makeBonusValue('敏捷') },
    ];
  }

  const SPIRIT_ATTRIBUTE_SYSTEM_OPTIONS = Object.freeze(['无', '元素', '五行']);
  const SPIRIT_ATTRIBUTE_TOKEN_OPTIONS = Object.freeze([
    '金',
    '木',
    '水',
    '火',
    '土',
    '风',
    '雷',
    '冰',
    '光',
    '暗',
    '精神',
    '空间',
    '时间',
    '创造',
    '毁灭',
  ]);
  const WUXING_ATTRIBUTE_TOKEN_OPTIONS = Object.freeze(['金', '木', '水', '火', '土']);
  const ELEMENT_ATTRIBUTE_TOKEN_OPTIONS = Object.freeze(['水', '火', '风', '土', '光', '暗']);
  const SKILL_LIMITED_ELEMENT_OPTIONS = Object.freeze(['五行类', '元素类', ...SPIRIT_ATTRIBUTE_TOKEN_OPTIONS]);
  function 规范化技能元素列表_桥接(value = []) {
    return Array.from(new Set(normalizeSkillDesignerArray(value).filter(token => SPIRIT_ATTRIBUTE_TOKEN_OPTIONS.includes(token))));
  }
  const RING_COLOR_META = Object.freeze({
    white: Object.freeze({ label: '白', glyph: '白', aliases: ['白色'] }),
    yellow: Object.freeze({ label: '黄', glyph: '黄', aliases: ['黄色'] }),
    purple: Object.freeze({ label: '紫', glyph: '紫', aliases: ['紫色'] }),
    black: Object.freeze({ label: '黑', glyph: '黑', aliases: ['黑色'] }),
    red: Object.freeze({ label: '红', glyph: '红', aliases: ['红色'] }),
    gold: Object.freeze({ label: '金', glyph: '金', aliases: ['金色'] }),
    orangegold: Object.freeze({ label: '橙金', glyph: '橙', aliases: ['橙', '橙色', '橙金色'] }),
    whitegold: Object.freeze({ label: '白金', glyph: '铂', aliases: ['白金色', '铂金'] }),
    silver: Object.freeze({ label: '银', glyph: '银', aliases: ['银色', '白银'] }),
    frostsilver: Object.freeze({ label: '霜银', glyph: '霜', aliases: ['霜银色'] }),
    moonwhite: Object.freeze({ label: '月白', glyph: '月', aliases: ['月白色'] }),
    iceblue: Object.freeze({ label: '冰蓝', glyph: '冰', aliases: ['冰蓝色', '冰青'] }),
    starblue: Object.freeze({ label: '星蓝', glyph: '星', aliases: ['星蓝色', '湛蓝'] }),
    cyan: Object.freeze({ label: '青', glyph: '青', aliases: ['青色', '天青'] }),
    teal: Object.freeze({ label: '海青', glyph: '海', aliases: ['海青色', '青碧'] }),
    jade: Object.freeze({ label: '碧玉', glyph: '碧', aliases: ['碧', '玉色', '青玉'] }),
    emerald: Object.freeze({ label: '翡翠', glyph: '翠', aliases: ['翡翠色', '翠绿', '翠色'] }),
    'green-gold': Object.freeze({ label: '绿金', glyph: '绿', aliases: ['绿金色', '翠金', '苍翠金'] }),
    'blue-gold': Object.freeze({ label: '蓝金', glyph: '蓝', aliases: ['蓝金色', '青金', '海金'] }),
    'purple-gold': Object.freeze({ label: '紫金', glyph: '鎏', aliases: ['紫金色'] }),
    'scarlet-gold': Object.freeze({ label: '赤金', glyph: '赤', aliases: ['赤金色', '绯金'] }),
    'rose-gold': Object.freeze({ label: '玫金', glyph: '玫', aliases: ['玫金色', '玫瑰金'] }),
    'amber-gold': Object.freeze({ label: '琥珀金', glyph: '琥', aliases: ['琥珀金色', '蜜金'] }),
    'obsidian-gold': Object.freeze({ label: '曜黑金', glyph: '曜', aliases: ['曜黑金色', '黑金', '玄金'] }),
    aurora: Object.freeze({ label: '极光', glyph: '极', aliases: ['极光色'] }),
    rainbow: Object.freeze({ label: '虹彩', glyph: '虹', aliases: ['虹彩色', '七彩', '幻彩'] }),
    crimson: Object.freeze({ label: '绯红', glyph: '绯', aliases: ['绯红色', '猩红', '血红'] }),
  });
  const RING_COLOR_OPTIONS = Object.freeze(Object.values(RING_COLOR_META).map(meta => meta.label));
  const RING_COLOR_ALIAS_MAP = Object.freeze(
    Object.entries(RING_COLOR_META).reduce((bucket, [key, meta]) => {
      [meta.label, ...(Array.isArray(meta.aliases) ? meta.aliases : [])].forEach(alias => {
        const label = toText(alias, '').trim();
        if (label) bucket[label] = key;
      });
      return bucket;
    }, {}),
  );

  function normalizeSpiritAttributeTokenList(value = []) {
    return normalizeEditorStringList(value).filter(token => SPIRIT_ATTRIBUTE_TOKEN_OPTIONS.includes(token));
  }

  function resolveSpiritAttributeUiState(spiritData = {}) {
    const rawSystem = normalizeSkillUiText(spiritData && spiritData['属性体系'], '无');
    const attributeSystem = SPIRIT_ATTRIBUTE_SYSTEM_OPTIONS.includes(rawSystem) ? rawSystem : '无';
    let callableElements = normalizeSpiritAttributeTokenList(spiritData && spiritData['可调用元素']);
    if (!callableElements.length) {
      if (attributeSystem === '五行') callableElements = [...WUXING_ATTRIBUTE_TOKEN_OPTIONS];
    }
    return {
      attributeSystem,
      callableElements,
    };
  }

  function resolveArmorPartData(armor, slotLabel) {
    const source = armor && typeof armor === 'object' ? armor : {};
    const aliasMap = {
      头盔: ['头盔', '头部', 'helmet'],
      胸铠: ['胸铠', '胸甲', 'chest'],
      左肩: ['左肩', '肩甲左', 'left_shoulder'],
      右肩: ['右肩', '肩甲右', 'right_shoulder'],
      左臂: ['左臂', '臂甲左', 'left_arm'],
      右臂: ['右臂', '臂甲右', 'right_arm'],
      左腿: ['左腿', '腿甲左', 'left_leg'],
      右腿: ['右腿', '腿甲右', 'right_leg'],
      战裙: ['战裙', '裙甲', 'skirt'],
      战靴: ['战靴', '靴子', 'boots'],
      戒指: ['戒指', 'ring'],
    };
    const aliases = aliasMap[slotLabel] || [slotLabel];
    for (const key of aliases) {
      const found =
        deepGet(source, ['部件', key], null) ||
        deepGet(source, ['部件', key], null) ||
        deepGet(source, ['slots', key], null) ||
        deepGet(source, ['components', key], null) ||
        deepGet(source, key, null);
      if (found) return found;
    }
    return null;
  }

  function buildArmoryActionRequest(snapshot, actionType) {
    if (!snapshot || !snapshot.rootData) return null;
    if (!isSnapshotPlayerControlled(snapshot)) return null;
    const activeKey = resolveSnapshotCharKey(snapshot, toText(snapshot.activeName, ''));
    if (!activeKey) return null;
    const chars = deepGet(snapshot, 'rootData.char', {});
    const activeChar = chars && typeof chars === 'object' ? chars[activeKey] || {} : {};
    const activeName = toText(
      activeChar && (activeChar.name || deepGet(activeChar, 'base.name', '')),
      toText(snapshot.activeName, activeKey),
    );
    const currentLoc = toText(deepGet(activeChar, '状态.位置', snapshot.currentLoc || '当前位置'), '当前位置')
      .replace(/^斗罗大陆-/, '')
      .replace(/^斗灵大陆-/, '');
    const armor = deepGet(activeChar, '装备.斗铠', {});
    const mech = deepGet(activeChar, '装备.机甲', {});
    const weapon = deepGet(activeChar, '装备.武器', {});
    const 防具 = deepGet(activeChar, '装备.防具', {});
    const armorName = toText(armor.名称 || armor['名称'], '当前斗铠');
    const mechName = toText(mech.名称 || mech['名称'] || mech.型号 || mech['型号'], '当前机甲');
    const actionMap = {
      equip_mech: {
        title: '装备机甲',
        playerInput: `我要在【${currentLoc}】装备机甲【${mechName}】。`,
        note: `请按 MVU 装备规则将 char.装备.机甲.装备状态 处理为“已装备”。若当前斗铠已装备且机甲不是红级，请同步处理斗铠卸下并清空对应 _属性加成。`,
      },
      unequip_mech: {
        title: '卸下机甲',
        playerInput: `我要在【${currentLoc}】解除机甲【${mechName}】的装载。`,
        note: `请将 char.装备.机甲.装备状态 处理为“未装备”，并将 机甲._属性加成 清零。`,
      },
      equip_armor: {
        title: '穿戴斗铠',
        playerInput: `我要在【${currentLoc}】穿戴斗铠【${armorName}】。`,
        note: `请按 MVU 装备规则尝试将 char.装备.斗铠.装备状态 处理为“已装备”。需要校验斗铠等级门槛（1字50级/2字70级/3字80级/4字90级）；若不满足则保持未装备并写入装备反噬。若当前已装备非红级机甲，斗铠不能保持已装备。`,
      },
      unequip_armor: {
        title: '卸下斗铠',
        playerInput: `我要在【${currentLoc}】解除斗铠【${armorName}】的装备状态。`,
        note: `请将 char.装备.斗铠.装备状态 处理为“未装备”，并将 斗铠._属性加成 清零。`,
      },
    };
    const actionMeta = actionMap[actionType];
    if (!actionMeta) return null;
    const systemPrompt = `以下内容属于前端发起的装备管理请求，不要在正文直接复述“系统提示 / 请求类型 / JSONPatch”等术语。\n\n[装备管理]\n角色：${activeName}\n地点：${currentLoc}\n动作：${actionMeta.title}\n当前斗铠：${summarizeArmoryValue(armor.名称 || armor['名称'] || armor.装备状态 || '无')}\n当前机甲：${summarizeArmoryValue(mech.名称 || mech['名称'] || mech.等级 || mech.装备状态 || '无')}\n当前主武器：${summarizeArmoryValue(weapon.名称 || weapon['名称'] || '无')}\n当前防具：${summarizeArmoryValue(防具.名称 || 防具['名称'] || 防具.装备状态 || '无')}\n\n${actionMeta.note}\n\n请将这次操作写成自然剧情，并在需要时同步更新角色的装备状态、相关装备字段与系统播报。`;
    return {
      playerInput: actionMeta.playerInput,
      systemPrompt,
      requestKind: 'equip_manage',
    };
  }

  function buildInventoryUseRequest(snapshot, meta = {}) {
    if (!snapshot || !snapshot.rootData) return null;
    if (!isSnapshotPlayerControlled(snapshot)) return null;
    const charKey =
      toText(meta && meta.charKey, '').trim() || resolveSnapshotCharKey(snapshot, toText(snapshot.activeName, ''));
    if (!charKey) return null;
    const chars = deepGet(snapshot, 'rootData.char', {});
    const activeChar = chars && typeof chars === 'object' ? chars[charKey] || {} : {};
    const activeName = toText(
      activeChar && (activeChar.name || deepGet(activeChar, 'base.name', '')),
      toText(snapshot.activeName, charKey),
    );
    const currentLoc = toText(deepGet(activeChar, '状态.位置', snapshot.currentLoc || '当前位置'), '当前位置')
      .replace(/^斗罗大陆-/, '')
      .replace(/^斗灵大陆-/, '');
    const itemName = toText(meta && meta.itemName, '未知物品');
    const actionLabel = toText(meta && meta.actionLabel, '使用');
    const summaryText = toText(meta && meta.summaryText, '已触发物品效果');
    const systemPrompt = `以下内容属于前端已经完成的背包${actionLabel}结算，不要在正文直接复述“系统提示 / JSONPatch / 变量更新 / 剧情推进请求”等术语。\n\n[背包${actionLabel}]\n角色：${activeName}\n地点：${currentLoc}\n动作：${actionLabel}\n物品：${itemName}\n已结算效果：${summaryText}\n\n请直接承接这次${actionLabel}续的自然剧情反馈，写出角色的即时体感、周围人的可见反应、局部环境变化与接下来的可推进空间。除非剧情上确有新增变化，不要重复结算同一批变量。`;
    return {
      playerInput: `我${actionLabel}了【${itemName}】。`,
      systemPrompt,
      requestKind: 'inventory_use',
    };
  }

  function buildConstructSkillUseRequest(snapshot, meta = {}) {
    if (!snapshot || !snapshot.rootData) return null;
    if (!isSnapshotPlayerControlled(snapshot)) return null;
    const charKey =
      toText(meta && meta.charKey, '').trim() || resolveSnapshotCharKey(snapshot, toText(snapshot.activeName, ''));
    if (!charKey) return null;
    const chars = deepGet(snapshot, 'rootData.char', {});
    const activeChar = chars && typeof chars === 'object' ? chars[charKey] || {} : {};
    const activeName = toText(
      activeChar && (activeChar.name || deepGet(activeChar, 'base.name', '')),
      toText(snapshot.activeName, charKey),
    );
    const currentLoc = toText(deepGet(activeChar, '状态.位置', snapshot.currentLoc || '当前位置'), '当前位置')
      .replace(/^斗罗大陆-/, '')
      .replace(/^斗灵大陆-/, '');
    const skillName = toText(meta && meta.skillName, '造物技能');
    const producedItems = Array.isArray(meta && meta.producedItems) ? meta.producedItems : [];
    const costText = toText(meta && meta.costText, '无');
    const itemSummary = producedItems.length ? producedItems.join('、') : '临时造物';
    const systemPrompt = `以下内容属于前端已经完成的日常造物施展结算，不要在正文直接复述“系统提示 / JSONPatch / 变量更新 / 剧情推进请求”等术语。\n\n[日常造物施展]\n角色：${activeName}\n地点：${currentLoc}\n技能：${skillName}\n生成结果：${itemSummary}\n资源消耗：${costText}\n\n请直接承接这次日常施展续的自然剧情反馈，写出施法表现、产物落成状态、周围环境或旁观者反应，以及它为后续剧情带来的可继续推进点。除非剧情上确有新增变化，不要重复结算同一批变量。`;
    return {
      playerInput: `我在【${currentLoc}】日常施展了【${skillName}】。`,
      systemPrompt,
      requestKind: 'daily_construct_cast',
    };
  }

  function makeInventoryGrid(items, 选项参数 = {}) {
    const attr = value =>
      String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
    const 网格类名 = toText(选项参数 && 选项参数.className, 'inventory-grid').trim() || 'inventory-grid';
    const 选中物品名 = toText(选项参数 && 选项参数.selectedName, '').trim();

    return `
        <div class="${attr(网格类名)}">
          ${(items || [])
            .map(
              item => {
                const 附加类名 = [item.className, item.品质类名, 选中物品名 && item.name === 选中物品名 ? 'is-selected' : '']
                  .map(值 => toText(值, '').trim())
                  .filter(Boolean)
                  .join(' ');
                return `
            <div class="inventory-cell mvu-inventory-slot ${attr(附加类名)}"
              data-item-definition-card="${attr(item.name)}"
              data-item-definition-name="${attr(item.name)}"
              data-quality-tier="${attr(item.品质档位 || '')}"
              data-hover-title="${attr(item.name)}"
              data-hover-char="${attr(item.charKey || '')}"
              data-hover-type="${attr(item.type || item.meta || '--')}"
              data-hover-rarity="${attr(item.rarity || '--')}"
              data-hover-qty="${attr(`×${item.qty}`)}"
              data-hover-count="${attr(item.qty)}"
              data-hover-source="${attr(item.source || '--')}"
              data-hover-expiry="${attr(item.expiry || '--')}"
              data-hover-usage="${attr(item.usage || item.meta || '--')}"
              data-hover-equip="${attr(item.canEquip ? 'true' : '')}"
              data-hover-usable="${attr(item.canUse ? 'true' : '')}"
              data-hover-action-label="${attr(item.actionLabel || '使用')}"
              data-hover-tags="${attr((item.tags || []).join('|'))}">
              <div class="cell-top">
                <b>${item.name}</b>
                <span class="qty inventory-qty-badge">×${item.qty}</span>
              </div>
              <div class="tier">${item.meta}</div>
            </div>
          `;
              },
            )
            .join('')}
        </div>
      `;
  }

  function makeSealColumn(items) {
    return `
        <div class="seal-column">
          ${(items || [])
            .map(
              item => `
            <div class="seal-node ${item.className || ''}">
              <span>${item.label}</span>
              <b>${item.state}</b>
            </div>
          `,
            )
            .join('')}
        </div>
      `;
  }

  function makeFactionLadder(items) {
    return `
        <div class="faction-ladder">
          ${(items || [])
            .map(
              item => `
            <div class="faction-row ${item.className || ''}">
              <b>${item.name}</b>
              <span>${item.desc}</span>
            </div>
          `,
            )
            .join('')}
        </div>
      `;
  }

  const modalPaginationState = Object.create(null);
  const modalFocusState = Object.create(null);

  function makeTimelineStack(items) {
    return `
        <div class="timeline-stack">
          ${(items || [])
            .map(item => {
              const 描述行列表 = Array.isArray(item && item.descLines)
                ? item.descLines.map(行 => toText(行, '').trim()).filter(Boolean)
                : [];
              const 描述内容 = 描述行列表.length
                ? 描述行列表.map(行 => `<em>${htmlEscape(行)}</em>`).join('')
                : 构建详情项值HTML(item && item.desc !== undefined ? { ...item, value: item.desc } : item);
              return `
            <div class="timeline-card${item && item.className ? ` ${item.className}` : ''}${item && item.preview ? ' clickable' : ''}"${item && item.preview ? ` data-preview="${escapeHtmlAttr(item.preview)}"` : ''}>
              <b>${item.title}</b>
              <span${描述行列表.length ? ' class="timeline-card-lines"' : ''}${item && item.descTitle ? ` title="${escapeHtmlAttr(toText(item.descTitle, ''))}"` : ''}>${描述内容}</span>
            </div>
          `;
            })
            .join('')}
        </div>
      `;
  }

  function makeDossierRows(items, className = '') {
    const rowItems = Array.isArray(items) ? items.filter(Boolean) : [];
    const columnCount = /\bdossier-row-grid--three\b/.test(className)
      ? 3
      : /\bdossier-row-grid--two\b/.test(className)
        ? 2
        : 1;
    const paddedItems = [];
    let usedSlots = 0;

    rowItems.forEach(item => {
      const itemClassName = item && item.className ? item.className : '';
      const isWide = columnCount > 1 && /\bdossier-row--wide\b/.test(itemClassName);

      if (isWide && usedSlots > 0) {
        while (usedSlots < columnCount) {
          paddedItems.push({ label: '\u00A0', value: '\u00A0', className: 'dossier-row--ghost' });
          usedSlots += 1;
        }
        usedSlots = 0;
      }

      paddedItems.push(item);

      if (columnCount === 1) return;
      if (isWide) {
        usedSlots = 0;
        return;
      }

      usedSlots += 1;
      if (usedSlots >= columnCount) usedSlots = 0;
    });

    if (columnCount > 1 && usedSlots > 0) {
      while (usedSlots < columnCount) {
        paddedItems.push({ label: '\u00A0', value: '\u00A0', className: 'dossier-row--ghost' });
        usedSlots += 1;
      }
    }

    return `
        <div class="dossier-row-grid ${className}">
          ${paddedItems
            .map(item => {
              const 空状态类 = 是空状态值(item && (item.displayText !== undefined ? item.displayText : item.value)) ? ' is-empty-state' : '';
              return `
            <div class="dossier-row${item && item.className ? ` ${item.className}` : ''}${空状态类}">
              <b class="dossier-field-label">${htmlEscape(toText(item && item.label, ''))}</b>
              <span class="dossier-field-value${空状态类}"${item && item.提示文本 ? ` title="${escapeHtmlAttr(item.提示文本)}"` : ''}>${构建详情项值HTML(item)}</span>
            </div>
          `;
            })
            .join('')}
        </div>
      `;
  }

  function makeDossierTags(items, className = '') {
    return `
        <div class="dossier-tag-row ${className}">
          ${(Array.isArray(items) ? items : []).map(item => `<span class="dossier-pill ${item && item.className ? item.className : ''}">${htmlEscape(toText(item && item.text, ''))}</span>`).join('')}
        </div>
      `;
  }

  function makeDossierList(items, className = '') {
    const listItems = Array.isArray(items) ? items : [];
    if (!listItems.length) return '';
    return `
        <div class="dossier-list ${className}">
          ${listItems
            .map(
              item => `
            <div class="dossier-list-row ${item && item.className ? item.className : ''} ${item && item.preview ? 'clickable' : ''}"${item && item.preview ? ` data-preview="${escapeHtmlAttr(item.preview)}"` : ''}>
              <b class="dossier-field-label">${htmlEscape(toText(item && item.title, ''))}</b>
              <span class="dossier-field-value">${item && item.desc !== undefined && item.desc !== null ? item.desc : ''}</span>
            </div>
          `,
            )
            .join('')}
        </div>
      `;
  }

  function makeDossierMeter(label, value, percent, className = '') {
    return `
        <div class="dossier-meter ${className}">
          <div class="dossier-meter-head">
            <b>${htmlEscape(toText(label, ''))}</b>
            <span>${value !== undefined && value !== null ? value : ''}</span>
          </div>
          <div class="dossier-meter-track"><div class="dossier-meter-fill" style="width:${Math.max(0, Math.min(100, toNumber(percent, 0)))}%;"></div></div>
        </div>
      `;
  }

  function paginateModalItems(items, previewKey, sectionKey, pageSize = 50) {
    const list = Array.isArray(items) ? items : [];
    const safePreviewKey = toText(previewKey, 'modal');
    const safeSectionKey = toText(sectionKey, 'section');
    const stateKey = `${safePreviewKey}::${safeSectionKey}`;
    const totalPages = Math.max(1, Math.ceil(list.length / Math.max(1, pageSize)));
    const currentPage = Math.max(1, Math.min(totalPages, toNumber(modalPaginationState[stateKey], 1) || 1));
    modalPaginationState[stateKey] = currentPage;
    const start = (currentPage - 1) * pageSize;
    return {
      stateKey,
      page: currentPage,
      totalPages,
      total: list.length,
      items: list.slice(start, start + pageSize),
    };
  }

  function makeModalPaginationControls(sectionKey, page, totalPages, total) {
    if (totalPages <= 1) return '';
    return `
        <div class="tag-cloud armory-quick-actions mvu-detail-toolbar">
          <button type="button" class="tag-chip clickable" data-page-nav="prev" data-page-section="${escapeHtmlAttr(sectionKey)}" ${page <= 1 ? 'disabled' : ''}>上一页</button>
          <span class="tag-chip">第 ${page} / ${totalPages} 页 · 共 ${total} 条</span>
          <button type="button" class="tag-chip clickable" data-page-nav="next" data-page-section="${escapeHtmlAttr(sectionKey)}" ${page >= totalPages ? 'disabled' : ''}>下一页</button>
        </div>
      `;
  }

  function buildEmptyRingLane(ringClass = 'ring-white', count = 10) {
    const 列表 = Array.from({ length: Math.max(1, Number(count) || 1) }).map(() => ({
      empty: true,
      ringClass,
    }));
    return 构建魂环阵列(列表, 'micro');
  }

