    const 值 = 格式化技能设计台原型字段值(condition['值'] ?? (类型 === '目标' ? '自身' : ''));
    const 状态 = normalizeSkillUiText(condition['状态'], '中毒');
    const 显示配置 = 读取技能设计台条件分支值控件配置(类型, 比较);
