function 读取显式交易物品价格(来源 = {}) {
  const 数据 = 来源 && typeof 来源 === 'object' && !Array.isArray(来源) ? 来源 : {};
  for (const 字段名 of ['基础价格', '价格']) {
    if (!Object.prototype.hasOwnProperty.call(数据, 字段名)) continue;
    const 原值 = 数据[字段名];
    if (原值 === undefined || 原值 === null || (typeof 原值 === 'string' && !原值.trim())) continue;
    const 数值 = Number(原值);
    if (Number.isFinite(数值)) return Math.max(0, Math.floor(数值));
  }
  return undefined;
}

class TradeUIComponent {
  constructor(container, snapshot, options = {}) {
    this.container = container;
    this.snapshot = snapshot;
    this.options = options;

    this.initDOM();
    this.bindEvents();
    this.syncData();
    this.applyInitialContext();
  }

  initDOM() {
    if (!document.getElementById('trade-ui-styles')) {
      const styleEl = document.createElement('style');
      styleEl.id = 'trade-ui-styles';
      styleEl.textContent = TradeStyles;
      document.head.appendChild(styleEl);
    }
    this.container.innerHTML = TradeTemplate;
  }

  $(selector) {
    return this.container.querySelector(selector);
  }

  $$ (selector) {
    return this.container.querySelectorAll(selector);
  }

  显示提示(消息, 类型 = 'error') {
    const 文本 = String(消息 || '').trim();
    if (!文本) return;
    if (typeof this.options.内联动作失败 === 'function') {
      try { this.options.内联动作失败({ 原因: 文本, 类型 }); } catch (错误) {}
    }
    const 窗口列表 = [];
    try { 窗口列表.push(window); } catch (错误) {}
    try {
      if (window.parent && window.parent !== window) 窗口列表.push(window.parent);
    } catch (错误) {}
    for (const 目标窗口 of 窗口列表) {
      try {
        if (目标窗口.MVU_Toast && typeof 目标窗口.MVU_Toast.show === 'function') {
          目标窗口.MVU_Toast.show(文本, 类型);
          return;
        }
        const 提示器 = 目标窗口.toastr;
        if (提示器 && typeof 提示器[类型] === 'function') {
          提示器[类型](文本);
          return;
        }
      } catch (错误) {}
    }
    if (类型 === 'error') console.warn(文本);
    else console.info(文本);
  }

  setActiveTab(targetId, shouldSync = true) {
    const safeTarget = String(targetId || '').trim();
    if (!safeTarget || !this.$(`#${safeTarget}`)) return false;
    this.$$('.trade-tab').forEach(tab => {
      tab.classList.toggle('active', tab.dataset.target === safeTarget);
    });
    this.$$('.tab-content').forEach(content => {
      content.classList.toggle('active', content.id === safeTarget);
    });
    if (shouldSync) this.syncData();
    return true;
  }

  getCurrentUiState() {
    return {
      activeTab: this.container.querySelector('.trade-tab.active')?.dataset.target || 'tab-shop',
      shopStore: this.$('#shop-store-sel')?.value || '',
      shopItem: this.$('#shop-item-sel')?.value || '',
      shopQty: this.$('#shop-qty')?.value || '1',
      sellItem: this.$('#sell-item-sel')?.value || '',
      sellQty: this.$('#sell-qty')?.value || '1',
      privAction: this.$('#priv-action')?.value || '私下买入',
      privNpc: this.$('#priv-npc')?.value || '',
      privItem: this.$('#priv-item')?.value || '',
      privQty: this.$('#priv-qty')?.value || '1',
      privPrice: this.$('#priv-price')?.value || '1000',
      aucItem: this.$('#auc-item-sel')?.value || '',
      aucBid: this.$('#auc-bid')?.value || '0'
    };
  }

  setSelectIfExists(selector, value) {
    const el = this.$(selector);
    if (!el) return;
    const hasValue = Array.from(el.options || []).some(opt => opt.value === value);
    if (hasValue) el.value = value;
  }

  restoreUiState(state = {}) {
    this.setSelectIfExists('#shop-store-sel', state.shopStore);
    this.updateShopItems();
    this.setSelectIfExists('#shop-item-sel', state.shopItem);
    if (this.$('#shop-qty')) this.$('#shop-qty').value = state.shopQty || '1';

    this.setSelectIfExists('#sell-item-sel', state.sellItem);
    if (this.$('#sell-qty')) this.$('#sell-qty').value = state.sellQty || '1';

    if (this.$('#priv-action')) this.$('#priv-action').value = state.privAction || '私下买入';
    if (this.$('#priv-npc')) this.$('#priv-npc').value = state.privNpc || '';
    if (this.$('#priv-item')) this.$('#priv-item').value = state.privItem || '';
    if (this.$('#priv-qty')) this.$('#priv-qty').value = state.privQty || '1';
    if (this.$('#priv-price')) this.$('#priv-price').value = state.privPrice || '1000';

    this.setSelectIfExists('#auc-item-sel', state.aucItem);
    if (this.$('#auc-bid')) this.$('#auc-bid').value = state.aucBid || '0';

    this.setActiveTab(state.activeTab || 'tab-shop', false);
    this.updateShopPreview();
    this.updateSellPreview();
    this.updatePrivPreview();
    this.updateAucPreview();
  }

  applyInitialContext() {
    const initialTab = String(this.options.initialTab || '').trim();
    if (initialTab) this.setActiveTab(initialTab, false);

    const prefillNpc = String(this.options.prefillNpc || '').trim();
    if (prefillNpc && this.$('#priv-npc')) {
      this.$('#priv-npc').value = prefillNpc;
      if (this.options.lockNpc === true) {
        this.$('#priv-npc').readOnly = true;
        const group = this.$('#priv-npc').closest('.form-group');
        if (group) group.classList.add('is-context-locked');
      }
    }

    const preferredStore = String(this.options.preferredStore || '').trim();
    const storeSel = this.$('#shop-store-sel');
    if (preferredStore && storeSel) {
      const hasStore = Array.from(storeSel.options || []).some(opt => opt.value === preferredStore);
      if (hasStore) storeSel.value = preferredStore;
    }

    this.updateShopItems();

    const prefillAction = String(this.options.prefillAction || '').trim();
    if (prefillAction && this.$('#priv-action')) {
      const actionText = /出售|卖出|sell/i.test(prefillAction) ? '私下卖出' : '私下买入';
      this.$('#priv-action').value = actionText;
    }

    const prefillItem = String(this.options.prefillItem || '').trim();
    if (prefillItem) {
      if (initialTab === 'tab-private' && this.$('#priv-item')) this.$('#priv-item').value = prefillItem;
      if (initialTab === 'tab-shop') this.setSelectIfExists('#shop-item-sel', prefillItem);
      if (initialTab === 'tab-sell') this.setSelectIfExists('#sell-item-sel', prefillItem);
      if (initialTab === 'tab-auction') this.setSelectIfExists('#auc-item-sel', prefillItem);
    } else if (initialTab === 'tab-private' && this.isBlackMarketPrivateTrade() && this.$('#priv-item')) {
      const storeName = this.getPrivateMarketStoreName(this.$('#priv-npc')?.value || '');
      const firstStockedItem = Object.entries(this.currentStores?.[storeName]?.库存 || {})
        .find(([, item]) => Number(item?.库存 || 0) > 0)?.[0] || '';
      if (firstStockedItem) this.$('#priv-item').value = firstStockedItem;
    }

    const prefillQty = Math.max(1, Number(this.options.prefillQty || this.options.数量 || 0));
    if (prefillQty > 0) {
      if (this.$('#shop-qty')) this.$('#shop-qty').value = String(prefillQty);
      if (this.$('#sell-qty')) this.$('#sell-qty').value = String(prefillQty);
      if (this.$('#priv-qty')) this.$('#priv-qty').value = String(prefillQty);
    }

    const prefillPrice = Math.max(0, Number(this.options.prefillPrice || this.options.价格 || 0));
    if (prefillPrice > 0) {
      if (this.$('#priv-price')) this.$('#priv-price').value = String(prefillPrice);
      if (this.$('#auc-bid')) this.$('#auc-bid').value = String(prefillPrice);
    }

    this.updateSellPreview();
    this.updatePrivPreview();
    this.updateAucPreview();

    if (this.options.autoExecute) {
      window.setTimeout(() => this.runInitialAutoExecute(), 80);
    }
  }

  runInitialAutoExecute() {
    const activeTab = this.container.querySelector('.trade-tab.active')?.dataset.target || 'tab-shop';
    if (activeTab === 'tab-shop' && !this.$('#btn-buy')?.disabled) this.executeShopBuy();
    else if (activeTab === 'tab-sell' && !this.$('#btn-sell')?.disabled) this.executeSell();
    else if (activeTab === 'tab-private' && !this.$('#btn-private')?.disabled) this.executePrivateTrade();
    else if (activeTab === 'tab-auction' && !this.$('#btn-auc')?.disabled) this.executeAuction();
  }

  bindEvents() {
    this.$$('.trade-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        this.setActiveTab(tab.dataset.target);
      });
    });

    // Shop Events
    this.$('#shop-store-sel').addEventListener('change', () => this.updateShopItems());
    this.$('#shop-item-sel').addEventListener('change', () => this.updateShopPreview());
    this.$('#shop-qty').addEventListener('input', () => this.updateShopPreview());
    this.$('#btn-buy').addEventListener('click', () => this.executeShopBuy());

    // Sell Events
    this.$('#sell-item-sel').addEventListener('change', () => this.updateSellPreview());
    this.$('#sell-qty').addEventListener('input', () => this.updateSellPreview());
    this.$('#btn-sell').addEventListener('click', () => this.executeSell());

    // Private Events
    this.$('#priv-action').addEventListener('change', () => this.updatePrivPreview());
    this.$('#priv-npc').addEventListener('input', () => this.updatePrivPreview());
    this.$('#priv-item').addEventListener('input', () => this.updatePrivPreview());
    this.$('#priv-qty').addEventListener('input', () => this.updatePrivPreview());
    this.$('#priv-price').addEventListener('input', () => this.updatePrivPreview());
    this.$('#btn-private').addEventListener('click', () => this.executePrivateTrade());

    // Auction Events
    this.$('#auc-item-sel').addEventListener('change', () => this.updateAucPreview());
    this.$('#auc-bid').addEventListener('input', () => this.updateAucPreview());
    this.$('#btn-auc').addEventListener('click', () => this.executeAuction());
  }

  updateData(newSnapshot) {
    const currentState = this.getCurrentUiState();
    this.snapshot = newSnapshot;
    this.syncData();
    this.restoreUiState(currentState);
  }

  destroy() {
    this.container.innerHTML = '';
  }

  get charData() {
    return this.snapshot?.activeChar || {};
  }

  get worldData() {
    return this.snapshot?.sd?.world || this.snapshot?.rootData?.world || {};
  }

  get rootData() {
    return this.snapshot?.sd || this.snapshot?.rootData || {};
  }

  get itemDefinitions() {
    const table = this.rootData?.物品;
    return table && typeof table === 'object' ? table : {};
  }

  规范化物品定义分类(分类 = '', fallback = '剧情杂物') {
    const 文本 = String(分类 || '').trim();
    return 交易物品定义分类集合.has(文本) ? 文本 : fallback;
  }

  遍历物品定义(回调 = () => {}) {
    const 物品表 = this.itemDefinitions;
    交易物品定义分类列表.forEach(分类 => {
      const 分类表 = 物品表 && typeof 物品表 === 'object' && !Array.isArray(物品表) ? 物品表[分类] : null;
      Object.entries(分类表 && typeof 分类表 === 'object' && !Array.isArray(分类表) ? 分类表 : {}).forEach(([物品名, 定义]) => {
        if (物品名 && 定义 && typeof 定义 === 'object' && !Array.isArray(定义)) 回调(物品名, 定义, 分类);
      });
    });
  }

  查找物品定义(物品名 = '') {
    const 名称 = String(物品名 || '').trim();
    if (!名称) return null;
    let 结果 = null;
    this.遍历物品定义((当前名, 定义, 分类) => {
      if (!结果 && 当前名 === 名称) 结果 = { 物品名: 当前名, 定义, 分类 };
    });
    return 结果;
  }

  查找运行时物品定义(物品名 = '') {
    const 名称 = String(物品名 || '').trim();
    if (!名称) return null;
    const 热区定义 = this.查找物品定义(名称);
    if (热区定义) return 热区定义;
    const 窗口列表 = [window];
    try { if (window.parent && window.parent !== window) 窗口列表.push(window.parent); } catch (错误) {}
    try { if (window.top && window.top !== window) 窗口列表.push(window.top); } catch (错误) {}
    for (const 当前窗口 of 窗口列表) {
      try {
        const 接口 = 当前窗口 && 当前窗口.__LWCS_MVU_RUNTIME_VIEW__;
        const 查找函数 = 接口 && typeof 接口.查找运行时物品定义 === 'function' ? 接口.查找运行时物品定义 : null;
        if (!查找函数) continue;
        const 命中 = 查找函数(this.rootData, 名称);
        if (命中 && 命中.定义 && typeof 命中.定义 === 'object') return 命中;
      } catch (错误) {}
    }
    return null;
  }

  取物品定义(物品名 = '') {
    return this.查找运行时物品定义(物品名)?.定义 || {};
  }

  读取物品定义显式分类(物品 = {}, fallback = '') {
    const 来源 = 物品 && typeof 物品 === 'object' && !Array.isArray(物品) ? 物品 : {};
    return this.规范化物品定义分类(来源.物品分类 || 来源.分类 || '', fallback);
  }

  要求物品定义分类(物品名 = '', 物品 = {}, 分类 = '') {
    const 分类名 = this.规范化物品定义分类(分类 || this.读取物品定义显式分类(物品, ''), '');
    if (!分类名) throw new Error(`交易物品缺少分类：${String(物品名 || '未命名').trim() || '未命名'}`);
    return 分类名;
  }

  规范化物品经济品质(品质 = '', 物品名 = '', 分类 = '') {
    const 文本 = String(品质 || '').trim();
    if (交易物品经济品质集合.has(文本)) return 文本;
    const 判定文本 = `${物品名} ${分类} ${文本}`;
    if (/超神器/.test(判定文本)) return '超神器';
    if (/神器|神级/.test(判定文本)) return '神器';
    if (/十万年|天锻|十二级|弑神|位面核心|极限斗罗|血脉核心|战略级/.test(判定文本)) return '传说';
    if (/万年|魂锻|灵锻|顶级|机密|高级|重型|最新型|九级|八级/.test(判定文本)) return '史诗';
    if (/千年|千锻|有灵合金|稀有|战术|秘密|特殊|特种|珍贵|军用/.test(判定文本)) return '稀有';
    if (/百年|黄级|优秀|高级制式/.test(判定文本)) return '优秀';
    return '普通';
  }

  复制JSON(值, fallback = {}) {
    if (值 === undefined || 值 === null) return fallback;
    try {
      return JSON.parse(JSON.stringify(值));
    } catch (错误) {
      return fallback;
    }
  }

  读取背包普通数量(记录 = {}) {
    const 来源 = 记录 && typeof 记录 === 'object' && !Array.isArray(记录) ? 记录 : {};
    return Math.max(0, Math.floor(Number(来源.数量 || 0)));
  }

  读取背包批次列表(记录 = {}) {
    const 来源 = 记录 && typeof 记录 === 'object' && !Array.isArray(记录) ? 记录 : {};
    return (Array.isArray(来源.批次) ? 来源.批次 : [])
      .map((批次, 索引) => ({ 批次, 索引 }))
      .filter(项 => 项.批次 && typeof 项.批次 === 'object' && !Array.isArray(项.批次) && Math.max(0, Math.floor(Number(项.批次.数量 || 0))) > 0);
  }

  读取背包总数量(记录 = {}) {
    const 来源 = 记录 && typeof 记录 === 'object' && !Array.isArray(记录) ? 记录 : {};
    const 普通数量 = this.读取背包普通数量(来源);
    const 批次数量 = this.读取背包批次列表(来源).reduce((总数, 项) => 总数 + Math.max(0, Math.floor(Number(项.批次?.数量 || 0))), 0);
    return 普通数量 + 批次数量;
  }

  编码出售引用(物品名 = '', 批次索引 = -1) {
    return JSON.stringify({ 物品名: String(物品名 || '').trim(), 批次索引: Number(批次索引) });
  }

  解码出售引用(引用 = '') {
    const 文本 = String(引用 || '').trim();
    if (!文本) return { 物品名: '', 批次索引: -1 };
    try {
      const 数据 = JSON.parse(文本);
      if (数据 && typeof 数据 === 'object' && !Array.isArray(数据)) {
        return {
          物品名: String(数据.物品名 || '').trim(),
          批次索引: Number.isFinite(Number(数据.批次索引)) ? Math.floor(Number(数据.批次索引)) : -1,
        };
      }
    } catch (错误) {}
    const 背包记录 = this.charData?.背包?.[文本];
    const 普通数量 = this.读取背包普通数量(背包记录);
    if (普通数量 > 0) return { 物品名: 文本, 批次索引: -1 };
    const 首批 = this.读取背包批次列表(背包记录)[0];
    return { 物品名: 文本, 批次索引: 首批 ? 首批.索引 : -1 };
  }

  读取出售引用上下文(引用 = '', 数量 = 1) {
    const { 物品名, 批次索引 } = this.解码出售引用(引用);
    const 背包记录 = this.charData?.背包?.[物品名];
    if (!物品名 || !背包记录) return null;
    const 目标数量 = Math.max(1, Math.floor(Number(数量 || 1)));
    const 命中定义 = this.查找物品定义(物品名);
    const 分类 = 命中定义?.分类 || '物品';
    if (批次索引 >= 0) {
      const 批次 = Array.isArray(背包记录.批次) ? 背包记录.批次[批次索引] : null;
      const 可用数量 = Math.max(0, Math.floor(Number(批次?.数量 || 0)));
      if (!批次 || 可用数量 <= 0) return null;
      return {
        物品名,
        分类,
        批次索引,
        可用数量,
        来源状态: { 数量: 0, 批次: [{ ...this.复制JSON(批次, {}), 数量: 可用数量 }] },
        展示物品: { ...(命中定义?.定义 || {}), ...(批次 || {}), 数量: 可用数量 },
      };
    }
    const 普通数量 = this.读取背包普通数量(背包记录);
    return {
      物品名,
      分类,
      批次索引: -1,
      可用数量: 普通数量,
      来源状态: { 数量: 普通数量 },
      展示物品: { ...(命中定义?.定义 || {}), 数量: 普通数量 },
    };
  }

  规范化交易批次(来源批次 = {}, 数量 = 1, fallback = {}) {
    const 来源 = 来源批次 && typeof 来源批次 === 'object' && !Array.isArray(来源批次) ? 来源批次 : {};
    const 输出 = {
      数量: Math.max(0, Math.floor(Number(数量 ?? 来源.数量 ?? 0))),
      品质: this.规范化物品经济品质(来源.品质 ?? fallback.品质 ?? fallback.rarity, fallback.物品名 || '', fallback.分类 || ''),
      品质系数: Math.max(0.1, Math.min(2, Number(来源.品质系数 ?? fallback.品质系数 ?? 1))),
      阶位: Math.max(0, Math.min(5, Math.floor(Number(来源.阶位 ?? fallback.阶位 ?? 0)))),
      基础金属: String(来源.基础金属 ?? fallback.基础金属 ?? '').trim(),
      魂导等级: Math.max(0, Math.min(12, Math.floor(Number(来源.魂导等级 ?? fallback.魂导等级 ?? 0)))),
      耐久: Math.max(0, Math.floor(Number(来源.耐久 ?? fallback.耐久 ?? 0))),
      剩余使用次数: Math.max(0, Math.floor(Number(来源.剩余使用次数 ?? fallback.剩余使用次数 ?? fallback.基础使用次数 ?? 0))),
      绑定者: String(来源.绑定者 ?? fallback.绑定者 ?? '').trim(),
      有效期至tick: Math.max(0, Math.floor(Number(来源.有效期至tick ?? fallback.有效期至tick ?? fallback.expiryTick ?? 0))),
    };
    const 融合参数 = 来源?.副职业参数?.融合参数 || fallback?.副职业参数?.融合参数;
    if (
      融合参数 &&
      typeof 融合参数 === 'object' &&
      !Array.isArray(融合参数) &&
      (融合参数.数量 !== undefined || 融合参数.融合率 !== undefined)
    ) {
      输出.副职业参数 = {
        融合参数: {
          数量: Math.max(1, Math.floor(Number(融合参数.数量 || 1))),
          融合率: Math.max(0, Math.min(100, Math.floor(Number(融合参数.融合率 ?? 100)))),
        },
      };
    }
    Object.keys(输出).forEach(键 => {
      const 值 = 输出[键];
      if (
        键 !== '数量' &&
        (值 === '' ||
          值 === 0 ||
          值 === '无' ||
          (键 === '阶位' && !(Number(来源.阶位 ?? fallback.阶位 ?? 0) > 0)) ||
          (键 === '剩余使用次数' && !(来源.剩余使用次数 !== undefined || fallback.剩余使用次数 !== undefined || Number(fallback.基础使用次数 || 0) > 0)) ||
          (键 === '魂导等级' && !(Number(来源.魂导等级 ?? fallback.魂导等级 ?? 0) > 0)) ||
          (键 === '品质' && 值 === '普通') ||
          (键 === '品质系数' && Number(值) === 1) ||
          (Array.isArray(值) && !值.length) ||
          (值 && typeof 值 === 'object' && !Array.isArray(值) && !Object.keys(值).length))
      ) delete 输出[键];
    });
    return 输出.数量 > 0 ? 输出 : null;
  }

  复制批次数量(批次列表 = [], 数量 = 1, fallback = {}) {
    let 剩余 = Math.max(0, Math.floor(Number(数量 || 0)));
    const 输出 = [];
    (Array.isArray(批次列表) ? 批次列表 : []).forEach(批次 => {
      if (剩余 <= 0) return;
      const 可取 = Math.min(剩余, Math.max(0, Math.floor(Number(批次?.数量 || 0))));
      const 新批次 = this.规范化交易批次(批次, 可取, fallback);
      if (新批次) {
        输出.push(新批次);
        剩余 -= 可取;
      }
    });
    return { 批次列表: 输出, 剩余数量: 剩余 };
  }

  需要批次入库(来源 = {}) {
    const 数据 = 来源 && typeof 来源 === 'object' && !Array.isArray(来源) ? 来源 : {};
    if (Array.isArray(数据.批次) && 数据.批次.length) return true;
    if (数据.品质系数 !== undefined && Number(数据.品质系数) !== 1) return true;
    if (
      数据.副职业参数?.融合参数 &&
      typeof 数据.副职业参数.融合参数 === 'object' &&
      !Array.isArray(数据.副职业参数.融合参数) &&
      (数据.副职业参数.融合参数.数量 !== undefined || 数据.副职业参数.融合参数.融合率 !== undefined)
    ) return true;
    if (数据.耐久 !== undefined || Number(数据.基础耐久 || 0) > 0) return true;
    if (数据.剩余使用次数 !== undefined || Number(数据.基础使用次数 || 0) > 0) return true;
    if (String(数据.基础金属 || '').trim()) return true;
    if (Number(数据.阶位 || 0) > 0) return true;
    if (Number(数据.魂导等级 || 0) > 0) return true;
    if (数据.基础耐久 !== undefined) return true;
    if (String(数据.绑定者 || '').trim()) return true;
    if (Number(数据.有效期至tick || 0) > 0) return true;
    return false;
  }

  构建交易入库批次(来源 = {}, 数量 = 1, fallback = {}) {
    const 数据 = 来源 && typeof 来源 === 'object' && !Array.isArray(来源) ? 来源 : {};
    if (Array.isArray(数据.批次) && 数据.批次.length) {
      return this.复制批次数量(数据.批次, 数量, fallback).批次列表;
    }
    if (!this.需要批次入库(数据)) return [];
    const 批次 = this.规范化交易批次(数据, 数量, fallback);
    return 批次 ? [批次] : [];
  }

  计算批次价格倍率(批次 = {}, 静态定义 = {}) {
    const 数据 = 批次 && typeof 批次 === 'object' && !Array.isArray(批次) ? 批次 : {};
    const 基准定义 = typeof 静态定义 === 'string' ? { 品质: 静态定义 } : 静态定义 && typeof 静态定义 === 'object' && !Array.isArray(静态定义) ? 静态定义 : {};
    const 基准品质 = this.规范化物品经济品质(基准定义.品质 ?? 基准定义.品级 ?? 基准定义.rarity ?? 数据.基础品质 ?? '普通');
    const 品质 = this.规范化物品经济品质(数据.品质 ?? '普通');
    const 品质倍率 = Number(交易物品经济品质倍率[品质] ?? 1) / Number(交易物品经济品质倍率[基准品质] ?? 1);
    const 品质系数 = Math.max(0.1, Math.min(2, Number(数据.品质系数 ?? 1)));
    const 融合率 = 数据?.副职业参数?.融合参数?.融合率;
    const 融合倍率 = 融合率 === undefined ? 1 : Math.max(0.8, Math.min(1.2, 0.8 + Number(融合率 ?? 0) / 250));
    return Math.max(0.01, 品质倍率 * 品质系数 * 融合倍率);
  }

  计算来源批次平均倍率(来源 = {}, 数量 = 1, 静态定义 = {}) {
    const 数据 = 来源 && typeof 来源 === 'object' && !Array.isArray(来源) ? 来源 : {};
    const 基准定义 = typeof 静态定义 === 'string' ? { 品质: 静态定义 } : 静态定义 && typeof 静态定义 === 'object' && !Array.isArray(静态定义) ? 静态定义 : {};
    const 目标数量 = Math.max(1, Math.floor(Number(数量 || 1)));
    const 批次结果 = Array.isArray(数据.批次) && 数据.批次.length
      ? this.复制批次数量(数据.批次, 目标数量, 基准定义)
      : { 批次列表: this.需要批次入库(数据) ? this.构建交易入库批次(数据, 目标数量, 基准定义) : [], 剩余数量: 0 };
    if (!批次结果.批次列表.length) return 1;
    const 加权 = 批次结果.批次列表.reduce((总和, 批次) => 总和 + this.计算批次价格倍率(批次, 基准定义) * Math.max(0, Number(批次.数量 || 0)), 0);
    const 数量合计 = 批次结果.批次列表.reduce((总和, 批次) => 总和 + Math.max(0, Number(批次.数量 || 0)), 0);
    return 数量合计 > 0 ? Math.max(0.01, 加权 / 数量合计) : 1;
  }

  构建背包扣减值(记录 = {}, 数量 = 1) {
    const 当前 = this.复制JSON(记录, {});
    let 剩余扣减 = Math.max(1, Math.floor(Number(数量 || 1)));
    const 批次列表 = Array.isArray(当前.批次) ? 当前.批次.map(批次 => this.复制JSON(批次, {})).filter(批次 => Math.max(0, Number(批次?.数量 || 0)) > 0) : [];
    for (const 批次 of 批次列表) {
      if (剩余扣减 <= 0) break;
      const 当前批次数量 = Math.max(0, Math.floor(Number(批次.数量 || 0)));
      const 扣减 = Math.min(当前批次数量, 剩余扣减);
      批次.数量 = 当前批次数量 - 扣减;
      剩余扣减 -= 扣减;
    }
    当前.批次 = 批次列表.filter(批次 => Math.max(0, Number(批次.数量 || 0)) > 0);
    if (剩余扣减 > 0) 当前.数量 = Math.max(0, Math.floor(Number(当前.数量 || 0)) - 剩余扣减);
    if (!当前.批次.length) delete 当前.批次;
    return this.读取背包总数量(当前) > 0 ? 当前 : null;
  }

  构建背包指定扣减值(记录 = {}, 数量 = 1, 批次索引 = null) {
    if (批次索引 === null || 批次索引 === undefined) return this.构建背包扣减值(记录, 数量);
    const 当前 = this.复制JSON(记录, {});
    const 扣减数量 = Math.max(1, Math.floor(Number(数量 || 1)));
    if (Number(批次索引) >= 0) {
      const 索引 = Math.floor(Number(批次索引));
      const 批次列表 = Array.isArray(当前.批次) ? 当前.批次.map(批次 => this.复制JSON(批次, {})) : [];
      if (!批次列表[索引]) return this.读取背包总数量(当前) > 0 ? 当前 : null;
      批次列表[索引].数量 = Math.max(0, Math.floor(Number(批次列表[索引].数量 || 0)) - 扣减数量);
      当前.批次 = 批次列表.filter(批次 => Math.max(0, Number(批次?.数量 || 0)) > 0);
      if (!当前.批次.length) delete 当前.批次;
    } else {
      当前.数量 = Math.max(0, Math.floor(Number(当前.数量 || 0)) - 扣减数量);
    }
    return this.读取背包总数量(当前) > 0 ? 当前 : null;
  }

  构建交易物品定义(物品名 = '', 来源物品 = {}, fallback = {}) {
    const 来源 = 来源物品 && typeof 来源物品 === 'object' && !Array.isArray(来源物品) ? JSON.parse(JSON.stringify(来源物品)) : {};
    const 分类 = this.要求物品定义分类(物品名, 来源, fallback.分类);
    const 基础价格 = this.读取交易物品基础价格(物品名, 来源, fallback, 分类);
    const 定义 = {
      品质: this.规范化物品经济品质(来源.品质 || fallback.rarity || 来源.品级 || '普通', 物品名, 分类),
      描述: 来源.描述 || fallback.desc || `获得了【${物品名}】。`,
      基础价格: 基础价格,
      默认货币: 来源.默认货币 || 来源.货币 || fallback.currency || this.getDefaultCurrencyByContext(fallback.storeName || fallback.source || '', this.charData?.状态?.位置 || '', fallback.storeData),
    };
    if (分类 === '锻造金属') {
      定义.阶位 = Math.max(0, Math.min(5, Math.floor(Number(来源.阶位 || 0))));
      const 金属特性 = Array.isArray(来源.金属特性)
        ? [...new Set(来源.金属特性.map(特性 => String(特性 || '').trim()).filter(Boolean))]
        : [];
      if (金属特性.length) 定义.金属特性 = 金属特性;
    }
    if (Number(来源.魂导等级 || 0) > 0) 定义.魂导等级 = Math.max(1, Math.min(12, Math.floor(Number(来源.魂导等级 || 0))));
    if (Number(来源.基础使用次数 || 0) > 0) 定义.基础使用次数 = Math.max(1, Math.floor(Number(来源.基础使用次数 || 1)));
    if (分类 === '魂灵') {
      if (String(来源.表象名称 || '').trim()) 定义.表象名称 = String(来源.表象名称 || '').trim();
      if (String(来源.标准物种 || '').trim()) 定义.标准物种 = String(来源.标准物种 || '').trim();
      if (Number(来源.年限 || 0) > 0) 定义.年限 = Math.max(1, Math.floor(Number(来源.年限 || 0)));
      if (String(来源.魂灵品质 || '').trim()) 定义.魂灵品质 = String(来源.魂灵品质 || '').trim().toUpperCase().replace('＋', '+');
      if (Number(来源.来源层数 || 0) > 0) 定义.来源层数 = Math.max(1, Math.floor(Number(来源.来源层数 || 0)));
    }
    if (交易装备物品分类集合.has(分类)) {
      if (来源.装备槽位) 定义.装备槽位 = 来源.装备槽位;
      if (Number(来源.基础耐久 || 0) > 0) 定义.基础耐久 = Math.max(0, Math.floor(Number(来源.基础耐久 || 0)));
      if (来源.属性加成 && typeof 来源.属性加成 === 'object' && !Array.isArray(来源.属性加成)) 定义.属性加成 = 来源.属性加成;
      if (来源.装备技能 && typeof 来源.装备技能 === 'object' && !Array.isArray(来源.装备技能)) 定义.装备技能 = 来源.装备技能;
      if (来源.附带魂技 && typeof 来源.附带魂技 === 'object' && !Array.isArray(来源.附带魂技)) 定义.附带魂技 = 来源.附带魂技;
    }
    if (交易可使用物品分类集合.has(分类)) {
      if (Array.isArray(来源.使用效果) && 来源.使用效果.length) {
        定义.使用效果 = 来源.使用效果.map(效果 => {
          if (!效果 || typeof 效果 !== 'object' || Array.isArray(效果)) return 效果;
          const 清理效果 = { ...效果 };
          delete 清理效果.描述;
          return 清理效果;
        });
      }
      if (Array.isArray(来源.副作用列表) && 来源.副作用列表.length) 定义.副作用列表 = 来源.副作用列表;
    }
    if (分类 === '设计图纸') {
      ['图纸目标', '材料'].forEach(字段名 => {
        if (来源[字段名] !== undefined && String(来源[字段名]).trim()) 定义[字段名] = 来源[字段名];
      });
    }
    if (来源.解锁内容 !== undefined) 定义.解锁内容 = 来源.解锁内容;
    if (分类 === '修炼秘籍') {
      if (来源.获取条件 !== undefined) 定义.获取条件 = 来源.获取条件;
      if (来源.研读条件 !== undefined) 定义.研读条件 = 来源.研读条件;
    }
    if (['身份凭证', '入场凭证'].includes(分类) && String(来源.使用限制或归属说明 || '').trim()) 定义.使用限制或归属说明 = String(来源.使用限制或归属说明).trim();
    Object.keys(定义).forEach(键 => {
      const 值 = 定义[键];
      if (值 === undefined || 值 === null || 值 === '' || (Array.isArray(值) && !值.length)) delete 定义[键];
      else if (值 && typeof 值 === 'object' && !Array.isArray(值) && !Object.keys(值).length) delete 定义[键];
    });
    return { 分类, 定义 };
  }

  get marketData() {
    return this.snapshot?.市场派生 || {};
  }

  get worldActionRuntime() {
    const roots = [window];
    try { if (window.parent && window.parent !== window) roots.push(window.parent); } catch (错误) {}
    try { if (window.top && window.top !== window && !roots.includes(window.top)) roots.push(window.top); } catch (错误) {}
    return roots.map(root => {
      try { return root && root.__LWCS_LIBRARY_DATA_RUNTIME_V1__; } catch (错误) { return null; }
    }).find(runtime => runtime && typeof runtime.resolveWorldActionContext === 'function') || null;
  }

  resolveWorldActionContext(actionType = 'trade', targetLocation = '', durationTicks = 0, temporaryRuleIds = []) {
    const runtime = this.worldActionRuntime;
    if (!runtime) return null;
    try {
      const context = runtime.resolveWorldActionContext({
        dataRoot: this.rootData || {},
        characterKey: this.activeName,
        actionType: String(actionType || 'trade'),
        targetLocation: String(targetLocation || this.charData?.状态?.位置 || ''),
        durationTicks: Math.max(0, Number(durationTicks || 0)),
        temporaryRuleIds: Array.isArray(temporaryRuleIds) ? temporaryRuleIds : [],
      });
      return context && typeof context === 'object' && !Array.isArray(context) ? context : null;
    } catch (错误) {
      return null;
    }
  }

  getConfiguredTradeWorldAction(defaultActionType) {
    const configuredActionType = String(this.options.actionType || '').trim();
    const actionType = ['trade_auction', 'trade_buy', 'trade_sell'].includes(configuredActionType)
      ? configuredActionType
      : defaultActionType;
    return {
      actionType,
      marketFunction: actionType === 'trade_auction' ? '拍卖' : '商业'
    };
  }

  isBlackMarketPrivateTrade() {
    return String(this.options.actionType || '').trim() === 'trade_private_black_market';
  }

  getPrivateMarketStoreName(targetName = '') {
    if (!this.isBlackMarketPrivateTrade()) return '';
    const candidates = [this.options.preferredStore, targetName]
      .map(name => String(name || '').trim())
      .filter(Boolean);
    return candidates.find(name => this.currentStores?.[name]) || '';
  }

  getWorldActionState(context, options = {}) {
    if (!context || typeof context !== 'object' || Array.isArray(context)) {
      return {
        ok: false,
        reason: '共享世界行动上下文不可用（runtime 缺失或调用失败）。'
      };
    }
    if (!Array.isArray(context.blockers) || context.blockers.some(item => typeof item !== 'string')) {
      return {
        ok: false,
        reason: '共享世界行动上下文结构无效。'
      };
    }
    const blockerText = context.blockers.find(item => item.trim());
    if (blockerText) return { ok: false, reason: blockerText };
    if (options.market === true) {
      const functionName = options.marketFunction || '商业';
      if (!context.facilities || typeof context.facilities !== 'object' || Array.isArray(context.facilities)) {
        return { ok: false, reason: '共享世界行动上下文结构无效。' };
      }
      if (!context.market || typeof context.market !== 'object' || Array.isArray(context.market) || !Number.isFinite(Number(context.market.价格倍率))) {
        return { ok: false, reason: '共享世界行动上下文结构无效。' };
      }
      const facility = context.facilities[functionName];
      if (!facility || typeof facility !== 'object' || Array.isArray(facility)) {
        return { ok: false, reason: `当前地点缺少${functionName}设施。` };
      }
      if (facility.可用 !== true) {
        return { ok: false, reason: String(facility.原因 || `当前${functionName}设施不可用。`).trim() };
      }
      if (options.storeName) {
        if (!context.market || typeof context.market !== 'object' || Array.isArray(context.market) || !Array.isArray(context.market.商店) || context.market.商店.some(item => typeof item !== 'string')) {
          return { ok: false, reason: '共享世界行动上下文结构无效。' };
        }
        if (!context.market.商店.includes(options.storeName)) {
          return { ok: false, reason: `当前地点没有商店【${options.storeName}】。` };
        }
      }
    }
    return { ok: true, reason: '' };
  }

  getWorldClockText(context) {
    const date = context?.time?.日期;
    if (!date || typeof date !== 'object' || Array.isArray(date)) return '';
    const hour = Number(date.时);
    const minute = Number(date.分);
    if (Number.isFinite(hour) && Number.isFinite(minute)) return `${String(Math.floor(hour)).padStart(2, '0')}:${String(Math.floor(minute)).padStart(2, '0')}`;
    return '';
  }

  get allChars() {
    return this.snapshot?.sd?.char || this.snapshot?.rootData?.char || {};
  }

  get activeName() {
    const chars = this.allChars || {};
    const snapshotActive = String(this.snapshot?.activeName || '').trim();
    if (snapshotActive && chars[snapshotActive]) return snapshotActive;

    const playerName = String(this.snapshot?.sd?.sys?.玩家名 || this.snapshot?.rootData?.sys?.玩家名 || '').trim();
    if (playerName && chars[playerName]) return playerName;
    if (chars['主角']) return '主角';

    const firstName = Object.keys(chars)[0];
    return firstName || '主角';
  }

  get eraRuntimeIntegration() {
    const roots = [window];
    try { if (window.parent && window.parent !== window) roots.push(window.parent); } catch (错误) {}
    try { if (window.top && window.top !== window && !roots.includes(window.top)) roots.push(window.top); } catch (错误) {}
    return roots.map(root => root && root.__LWCS_ERA_RUNTIME_INTEGRATION_V1__)
      .find(runtime => runtime && typeof runtime.resolveEraAtTick === 'function') || null;
  }

  get eraCurrencyRegistry() {
    const roots = [window];
    try { if (window.parent && window.parent !== window) roots.push(window.parent); } catch (错误) {}
    try { if (window.top && window.top !== window && !roots.includes(window.top)) roots.push(window.top); } catch (错误) {}
    return roots.map(root => root && root.__LWCS_ERA_CURRENCY_REGISTRY_V1__)
      .find(runtime => runtime && typeof runtime.resolveCurrency === 'function') || null;
  }

  get currentEraId() {
    const integration = this.eraRuntimeIntegration;
    const tick = Math.max(0, Number(this.worldData?.时间?.tick || 0));
    try { return integration?.resolveEraAtTick(tick)?.eraId || 'current'; } catch (错误) { return 'current'; }
  }

  get activeCharBasePath() {
    return `/char/${this.escapeJsonPointer(this.activeName)}`;
  }

  getCurrencyLabel(currency) {
    const token = String(currency || '').trim();
    const result = this.eraCurrencyRegistry?.resolveCurrency(this.currentEraId, token);
    if (result?.status === 'resolved') return result.definition?.显示名 || result.definition?.名称 || token;
    return token || '未知货币';
  }

  getDefaultCurrencyByContext(storeName = '', loc = '', storeData = null) {
    const storeText = String(storeName || '');
    const locText = String(loc || this.charData?.状态?.位置 || '');
    const storeFaction = String(storeData?.所属势力 || '');
    const merged = `${storeText}|${locText}|${storeFaction}`;
    const registry = this.eraCurrencyRegistry;
    const result = registry?.resolveTradeCurrency(this.currentEraId, '', merged);
    return result?.status === 'resolved' ? result.currency : (this.currentEraId === 'dldl' || this.currentEraId === 'jueshitangmen' ? '金魂币' : '联邦币');
  }

  resolveTradeCurrency(item = {}, storeName = '', loc = '', storeData = null) {
    const explicit = String(item?.货币 || item?.默认货币 || '').trim();
    const merged = `${String(storeName || '')}|${String(loc || this.charData?.状态?.位置 || '')}|${String(storeData?.所属势力 || '')}`;
    const result = this.eraCurrencyRegistry?.resolveTradeCurrency(this.currentEraId, explicit, merged);
    return result?.currency || this.getDefaultCurrencyByContext(storeName, loc, storeData);
  }

  isCurrencySpendable(currency) {
    return this.eraCurrencyRegistry?.isDirectlySpendable(this.currentEraId, String(currency || '').trim()) === true;
  }

  getCurrencyBlockedMessage(currency) {
    const result = this.eraCurrencyRegistry?.resolveCurrency(this.currentEraId, String(currency || '').trim());
    if (result?.reason === 'identity-item-excluded') return '徽章、勋章和入场凭证是身份物品，不能当作货币直接交易。';
    if (result?.status === 'resolved' && result.definition?.种类 === this.eraCurrencyRegistry.currencyKinds?.军功) return '军功不能直接用于购物，只能用于军方晋升、审批或资格申领。';
    return '当前货币不可直接用于交易。';
  }

  syncData() {
    const loc = this.charData?.状态?.位置 || "未知区域";
    const fame = this.charData?.社交?.声望 || 0;
    const currentCity = this.resolveTradeLocationNode(loc);
    this.tradeContext = this.resolveWorldActionContext('trade', loc);
    const displayCurrency = this.resolveTradeCurrency({}, '', loc, currentCity?.data);
    const displayBalance = Number(this.charData?.财富?.[displayCurrency] || 0);

    this.$('#ui-loc').textContent = loc;
    this.$('#ui-currency-label').textContent = this.getCurrencyLabel(displayCurrency);
    this.$('#ui-fedcoin').textContent = displayBalance.toLocaleString();
    this.$('#ui-fame').textContent = fame.toLocaleString();

    const currentStores = JSON.parse(JSON.stringify(currentCity?.data?.商店 || {}));
    if (this.canAccessSoulTowerDiscountStore(loc, currentCity, this.tradeContext)) {
      const discountStore = this.buildSoulTowerDiscountStoreEntry();
      if (discountStore) currentStores[SOUL_TOWER_DISCOUNT_STORE_NAME] = discountStore;
    }
    this.currentStores = currentStores;
    this.currentAuction = this.worldData?.拍卖 || { 状态: "休市", 拍品: {} };

    this.populateShopData();
    this.populateSellData();
    this.populateAuctionData();
    this.updatePrivPreview();
  }

  // --- 估值与上下文 ---
  读取交易物品基础价格(物品名 = '', 来源 = {}, fallback = {}, 分类 = '物品') {
    const 来源价格 = 读取显式交易物品价格(来源);
    if (来源价格 !== undefined) return 来源价格;
    const 回退价格 = 读取显式交易物品价格(fallback);
    if (回退价格 !== undefined) return 回退价格;
    return this.estimateBasePrice(物品名, 分类);
  }

  estimateBasePrice(itemName, itemType = "物品") {
    const definitionPrice = 读取显式交易物品价格(this.取物品定义(itemName));
    if (definitionPrice !== undefined) return definitionPrice;
    if (/斗铠/.test(itemName)) return 0;
    if (/机甲/.test(itemName)) {
      if (/红级/.test(itemName)) return 5000000000;
      if (/黑级/.test(itemName)) return 1000000000;
      if (/紫级/.test(itemName)) return 80000000;
      if (/黄级/.test(itemName)) return 6000000;
      return 6000000;
    }
    let tier = 1;
    if (/天锻|十万年/.test(itemName)) tier = 5;
    else if (/魂锻|万年/.test(itemName)) tier = 4;
    else if (/灵锻|千年/.test(itemName)) tier = 3;
    else if (/千锻|百年/.test(itemName)) tier = 2;
    else if (/百锻/.test(itemName)) tier = 1;

    let metalBasePrice = 10000;
    if (tier === 5) metalBasePrice = 500000000;
    else if (tier === 4) metalBasePrice = 80000000;
    else if (tier === 3) metalBasePrice = 10000000;
    else if (tier === 2) metalBasePrice = 500000;
    else if (tier === 1) metalBasePrice = 50000;

    let metalCount = 1;
    let match = itemName.match(/(\d+)种金属/);
    if (match) metalCount = parseInt(match[1]);
    else if (/融锻/.test(itemName)) metalCount = 2;

    let totalMetalPrice = metalBasePrice * (1 + (metalCount - 1) * 0.3);

    if (itemType === "图纸") return Math.floor(totalMetalPrice * 0.2);
    else if (itemType === "消耗品" || itemType === "修复品") return Math.floor(totalMetalPrice * 0.1);
    else return Math.floor(totalMetalPrice * 1.0);
  }

  clampMarketMultiplier(value) {
    const num = Number(value);
    if (!Number.isFinite(num)) return 1;
    return Math.max(0.7, Math.min(1.6, num));
  }

  getMarketMultiplier(kind = 'buy', context = null) {
    return this.clampMarketMultiplier(context?.market?.价格倍率);
  }

  getMarketAdjustedPrice(basePrice, kind = 'buy', options = {}) {
    const base = Math.max(0, Math.floor(Number(basePrice || 0)));
    if (options.fixed === true) return base;
    return Math.max(0, Math.floor(base * this.getMarketMultiplier(kind, options.context)));
  }

  getMarketAdjustmentText(kind = 'buy', options = {}) {
    if (options.fixed === true) return '固定价格';
    const context = options.context || null;
    return String(context?.market?.经济状况 || '按当前区域供需结算').trim();
  }

  clampTrade(value, min, max) {
    return Math.max(min, Math.min(max, Number(value || 0)));
  }

  normalizeLocForMatch(location) {
    const raw = String(location || '').replace(/^斗罗大陆-/, '').replace(/^斗灵大陆-/, '').trim();
    const segments = raw.split('-').filter(Boolean);
    return {
      raw,
      leaf: segments[segments.length - 1] || raw,
      segments
    };
  }

  resolveCharacterByName(name) {
    const target = String(name || '').trim();
    const chars = this.allChars && typeof this.allChars === 'object' ? this.allChars : {};
    if (!target) return { key: '', displayName: '', char: null };
    if (chars[target]) {
      const charInfo = chars[target];
      const displayName = String(charInfo?.name || charInfo?.base?.name || target).trim() || target;
      return { key: target, displayName, char: charInfo };
    }
    for (const [charKey, charInfo] of Object.entries(chars)) {
      const displayName = String(charInfo?.name || charInfo?.base?.name || charKey).trim() || charKey;
      if (displayName === target) {
        return { key: charKey, displayName, char: charInfo };
      }
    }
    return { key: '', displayName: target, char: null };
  }

  isLocationCompatible(currentLoc, targetLoc) {
    const current = this.normalizeLocForMatch(currentLoc);
    const target = this.normalizeLocForMatch(targetLoc);
    if (!current.raw || !target.raw) return current.raw === target.raw;
    if (current.raw === target.raw || current.leaf === target.leaf) return true;
    return current.segments.some(seg => target.segments.includes(seg));
  }

  当前地点可参与本期拍卖() {
    const 拍卖 = this.currentAuction && typeof this.currentAuction === 'object' ? this.currentAuction : {};
    const 拍品表 = 拍卖.拍品 && typeof 拍卖.拍品 === 'object' && !Array.isArray(拍卖.拍品) ? 拍卖.拍品 : {};
    if (String(拍卖.状态 || '休市') === '休市' || !Object.keys(拍品表).length) return false;
    const worldContext = this.resolveWorldActionContext('trade_auction', this.charData?.状态?.位置 || '');
    if (!this.getWorldActionState(worldContext, { market: true, marketFunction: '拍卖' }).ok) return false;
    const 拍卖地点 = String(拍卖.地点 || '').trim();
    const 当前位置 = String(this.charData?.状态?.位置 || '').trim();
    if (!拍卖地点 || 拍卖地点 === '无' || !当前位置) return false;
    const 当前地点 = this.normalizeLocForMatch(当前位置);
    const 目标地点 = this.normalizeLocForMatch(拍卖地点);
    if (当前地点.raw === 目标地点.raw) return true;
    if (目标地点.segments.length <= 1 && 当前地点.leaf === 目标地点.leaf) return true;
    if (当前地点.leaf === 目标地点.leaf && 当前地点.segments[0] && 当前地点.segments[0] === 目标地点.segments[0]) return true;
    if (当前地点.raw.includes(目标地点.raw)) return true;
    if (当前地点.segments[0] && 当前地点.segments[0] === 目标地点.segments[0] && /拍卖|交易中心/.test(当前地点.raw)) return true;
    return 当前地点.segments[0] === 目标地点.segments[0]
      && 当前地点.segments.some(片段 => 片段 && 目标地点.segments.includes(片段) && /拍卖|交易中心/.test(当前地点.raw));
  }

  resolveTradeLocationNode(location) {
    const worldLocations = this.worldData?.地点 || {};
    const raw = String(location || '').trim();
    const normalized = this.normalizeLocForMatch(raw);
    const candidates = [raw, normalized.raw].filter(Boolean);
    for (const key of candidates) {
      if (worldLocations[key]) return { key, data: worldLocations[key] };
    }
    return { key: '', data: null };
  }

  getPrivateTradeContext(action, targetNpcName, itemName, qty, price) {
    const ctx = {
      action, targetNpcName, targetChar: null, relationScore: 0, successRate: 0,
      basePrice: Math.max(0, this.estimateBasePrice(itemName, "物品")),
      marketPrice: 0,
      total: Math.max(0, Number(price || 0) * Math.max(1, Number(qty || 1))),
      error: null, note: '', npcItem: null, playerItem: null
    };
    if (!itemName) { ctx.error = '请输入交易物品名称。'; return ctx; }
    ctx.isBlackMarket = this.isBlackMarketPrivateTrade();
    ctx.storeName = this.getPrivateMarketStoreName(targetNpcName);
    ctx.usesMarketStore = ctx.isBlackMarket && !!ctx.storeName;
    ctx.counterparty = ctx.usesMarketStore ? ctx.storeName : targetNpcName;
    if (!ctx.isBlackMarket && !targetNpcName) { ctx.error = '请输入交易对象 NPC。'; return ctx; }
    if (ctx.isBlackMarket && (!targetNpcName || targetNpcName === '黑市渠道') && !ctx.usesMarketStore) {
      ctx.error = '请选择在场交易对象，或从带有库存的黑市渠道进入交易。'; return ctx;
    }
    const currentLoc = String(this.charData?.状态?.位置 || '');
    const currentLocation = this.resolveTradeLocationNode(currentLoc);
    ctx.locationKey = currentLocation.key || currentLoc;
    ctx.storeData = ctx.usesMarketStore ? this.currentStores?.[ctx.storeName] || null : null;
    ctx.worldContext = this.resolveWorldActionContext(ctx.isBlackMarket ? 'trade_private_black_market' : 'trade_private', currentLoc);
    const privateActionState = this.getWorldActionState(ctx.worldContext, ctx.isBlackMarket
      ? { market: true, marketFunction: '黑市', ...(ctx.usesMarketStore ? { storeName: ctx.storeName } : {}) }
      : {});
    if (!privateActionState.ok) { ctx.error = privateActionState.reason; return ctx; }

    if (!ctx.usesMarketStore) {
      const resolvedTarget = this.resolveCharacterByName(targetNpcName);
      const targetChar = resolvedTarget.char;
      const relationName = resolvedTarget.displayName || targetNpcName;
      ctx.targetChar = targetChar || null;
      if (!targetChar) { ctx.error = `找不到交易对象【${targetNpcName}】。`; return ctx; }
      const targetLoc = String(targetChar?.状态?.位置 || '');
      if (currentLoc && targetLoc && !this.isLocationCompatible(currentLoc, targetLoc)) {
        ctx.error = `【${targetNpcName}】当前不在你身边，无法进行私下交易。`; return ctx;
      }
      ctx.relationScore = Number(this.charData?.社交?.关系?.[targetNpcName]?.好感度 || this.charData?.社交?.关系?.[relationName]?.好感度 || 0);
    }
    if (action === "私下买入") {
      ctx.npcItem = ctx.usesMarketStore
        ? ctx.storeData?.库存?.[itemName] || null
        : ctx.targetChar?.背包?.[itemName] || null;
      const itemDefinition = ctx.npcItem?._临时定义 || this.取物品定义(itemName);
      const itemBasePrice = this.读取交易物品基础价格(
        itemName,
        { ...(itemDefinition || {}), ...(ctx.npcItem || {}) },
        itemDefinition,
        itemDefinition?.分类 || '剧情杂物',
      );
      ctx.basePrice = Math.max(0, Math.floor(
        itemBasePrice
        * this.计算来源批次平均倍率(ctx.npcItem || {}, qty, itemDefinition)
        * (ctx.usesMarketStore ? Number(ctx.npcItem?.价格倍率 || 1) * Math.max(0, 1 - Number(ctx.npcItem?.折扣 || 0)) : 1)
      ));
      if (ctx.basePrice <= 0) {
        ctx.error = `【${itemName}】当前无法进行可靠估值，私下交易无法发起。`; return ctx;
      }
      ctx.marketPrice = this.getMarketAdjustedPrice(ctx.basePrice, 'buy', { context: ctx.worldContext });
      ctx.currency = this.resolveTradeCurrency(ctx.npcItem || itemDefinition, ctx.storeName, currentLoc, ctx.storeData);
      const priceDeltaRatio = (Number(price || 0) - ctx.marketPrice) / Math.max(1, ctx.marketPrice);
      if ((this.charData?.财富?.[ctx.currency] || 0) < ctx.total) {
        ctx.error = `${this.getCurrencyLabel(ctx.currency)}不足，完成该交易需要 ${ctx.total.toLocaleString()}。`; return ctx;
      }
      const availableQuantity = ctx.usesMarketStore ? Number(ctx.npcItem?.库存 || 0) : this.读取背包总数量(ctx.npcItem);
      if (!ctx.npcItem || availableQuantity < qty) {
        ctx.error = `【${ctx.counterparty}】当前并没有足够的【${itemName}】可供出售。`; return ctx;
      }
      ctx.successRate = this.clampTrade(60 + Math.floor(ctx.relationScore * 0.25) + Math.floor(priceDeltaRatio * 50), 5, 95);
      ctx.note = ctx.usesMarketStore
        ? `黑市渠道 ${ctx.storeName} / 参考价 ${ctx.marketPrice.toLocaleString()} / 按当前区域供需与报价结算`
        : `${ctx.isBlackMarket ? '黑市环境 / ' : ''}好感 ${ctx.relationScore} / 参考价 ${ctx.marketPrice.toLocaleString()} / 按当前区域供需与关系结算`;
    } else {
      ctx.playerItem = this.charData?.背包?.[itemName] || null;
      const itemDefinition = this.取物品定义(itemName);
      const itemBasePrice = this.读取交易物品基础价格(
        itemName,
        { ...(itemDefinition || {}), ...(ctx.playerItem || {}) },
        itemDefinition,
        itemDefinition?.分类 || '剧情杂物',
      );
      ctx.basePrice = Math.max(0, Math.floor(itemBasePrice * this.计算来源批次平均倍率(ctx.playerItem || {}, qty, itemDefinition)));
      if (ctx.basePrice <= 0) {
        ctx.error = `【${itemName}】当前无法进行可靠估值，私下交易无法发起。`; return ctx;
      }
      ctx.marketPrice = this.getMarketAdjustedPrice(ctx.basePrice, 'sell', { context: ctx.worldContext });
      ctx.currency = this.resolveTradeCurrency(ctx.playerItem || this.取物品定义(itemName), ctx.storeName, currentLoc, ctx.storeData);
      const priceDeltaRatio = (Number(price || 0) - ctx.marketPrice) / Math.max(1, ctx.marketPrice);
      if (!ctx.playerItem || this.读取背包总数量(ctx.playerItem) < qty) {
        ctx.error = '背包数量不足。'; return ctx;
      }
      if (!ctx.usesMarketStore && (ctx.targetChar?.财富?.[ctx.currency] || 0) < ctx.total) {
        ctx.error = `【${targetNpcName}】的${this.getCurrencyLabel(ctx.currency)}不足，无法完成这笔收购。`; return ctx;
      }
      ctx.successRate = this.clampTrade(60 + Math.floor(ctx.relationScore * 0.25) - Math.floor(priceDeltaRatio * 55), 5, 95);
      ctx.note = ctx.usesMarketStore
        ? `黑市渠道 ${ctx.storeName} / 参考价 ${ctx.marketPrice.toLocaleString()} / 按当前区域供需与报价结算`
        : `${ctx.isBlackMarket ? '黑市环境 / ' : ''}好感 ${ctx.relationScore} / 参考价 ${ctx.marketPrice.toLocaleString()} / 按当前区域供需与关系结算`;
    }
    if (!this.isCurrencySpendable(ctx.currency)) {
      ctx.error = this.getCurrencyBlockedMessage(ctx.currency);
    }
    return ctx;
  }

  解析交易物品价格(物品名, 选项 = {}) {
    const 名称 = String(物品名 || '').trim();
    const 数量 = Math.max(1, Math.floor(Number(选项.数量 || 1)));
    const 来源物品 = 选项.物品 && typeof 选项.物品 === 'object' && !Array.isArray(选项.物品) ? 选项.物品 : {};
    const 命中定义 = this.查找运行时物品定义(名称);
    const 分类 = this.规范化物品定义分类(命中定义?.分类 || 来源物品.物品分类 || 来源物品.分类 || 选项.分类 || '剧情杂物');
    const 定义 = { ...(命中定义?.定义 || {}), ...来源物品 };
    const 基础价格 = this.读取交易物品基础价格(名称, 定义, {}, 分类);
    const 基础单价 = Math.max(0, Math.floor(基础价格 * this.计算来源批次平均倍率(定义, 数量, 命中定义?.定义 || 定义)));
    const 方向 = /sell|出售|卖出/i.test(String(选项.方向 || 'buy')) ? 'sell' : 'buy';
    const 世界行动上下文 = 选项.世界行动上下文 || this.resolveWorldActionContext(
      `trade_${方向}`,
      String(选项.地点 || 选项.位置 || this.charData?.状态?.位置 || ''),
      Math.max(0, Number(选项.durationTicks || 选项.持续tick || 0))
    );
    const 实际单价 = this.getMarketAdjustedPrice(方向 === 'sell' ? Math.floor(基础单价 * 0.5) : 基础单价, 方向, {
      fixed: 选项.fixed === true,
      context: 世界行动上下文,
    });
    const 信息 = this.resolveTradeItemInfo(名称, 定义, { 分类, source: 选项.来源 || '统一估价' });
    return {
      物品名: 名称,
      分类,
      数量,
      基础单价,
      实际单价,
      总价: 实际单价 * 数量,
      货币: this.resolveTradeCurrency(定义, 选项.商店 || 选项.来源 || '', this.charData?.状态?.位置 || '', 选项.商店数据 || null),
      信息,
    };
  }

  formatTickToCalendarDateText(tickValue) {
    const safeTick = Math.max(0, Number(tickValue || 0));
    const totalMinutes = Math.round(safeTick * 10);
    const days = Math.floor(totalMinutes / (24 * 60));
    const years = Math.floor(days / 360);
    const months = Math.floor((days % 360) / 30) + 1;
    const currentDay = (days % 30) + 1;
    const remainderMinutes = totalMinutes % (24 * 60);
    const hours = Math.floor(remainderMinutes / 60);
    const mins = Math.floor(remainderMinutes % 60);
    return `斗罗历${years}年${months}月${currentDay}日 ${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
  }

  isShopOpenNow(context = null, storeName = '') {
    return this.getWorldActionState(context, { market: true, storeName }).ok;
  }

  getShopOpenStateText(context = null, storeName = '') {
    const clockText = this.getWorldClockText(context);
    const state = this.getWorldActionState(context, { market: true, storeName });
    if (!context) return state.reason;
    if (!state.ok) return `${state.reason}${clockText ? ` · 当前时间 ${clockText}` : ''}`;
    return `营业中${clockText ? ` ${clockText}` : ''}`;
  }

  resolveTradeItemInfo(itemName, item = {}, fallback = {}) {
    const 命中定义 = this.查找运行时物品定义(itemName);
    const safeItem = { ...(命中定义?.定义 || {}), ...(item && typeof item === 'object' ? item : {}) };
    const type = String(this.规范化物品定义分类(命中定义?.分类 || fallback.分类 || this.读取物品定义显式分类(safeItem, ''), '剧情杂物'));
    const rarity = String(safeItem.品质 || fallback.rarity || '普通');
    const expiryTick = Number(safeItem.有效期至tick ?? fallback.expiryTick ?? 0);
    const expiry = expiryTick > 0 ? this.formatTickToCalendarDateText(expiryTick) : (String(fallback.expiry || '').trim() || '无期限');
    const trigger = '使用';
    const source = String(safeItem.来源 || safeItem.绑定者 || fallback.source || '常规流通');
    const desc = String(safeItem.描述 || fallback.desc || '暂无说明');
    return {
      name: itemName,
      type,
      rarity,
      trigger,
      expiry,
      source,
      desc,
      expiryTick,
      temporary: expiryTick > 0 || expiry !== '无期限'
    };
  }

  updateTradeMetaPanel(prefix, info = null) {
    const triggerEl = this.$(`#${prefix}-trigger`);
    const expiryEl = this.$(`#${prefix}-expiry`);
    const sourceEl = this.$(`#${prefix}-source`);
    const descEl = this.$(`#${prefix}-desc`);
    if (!triggerEl || !expiryEl || !sourceEl || !descEl) return;
    if (!info) {
      triggerEl.textContent = '-';
      expiryEl.textContent = '-';
      sourceEl.textContent = '-';
      descEl.textContent = '-';
      return;
    }
    triggerEl.textContent = info.trigger || '-';
    expiryEl.textContent = info.expiry || '-';
    sourceEl.textContent = info.source || '-';
    descEl.textContent = info.desc || '-';
  }

  buildInventoryItemFromTradeSource(itemName, sourceItem = {}, qty = 1, fallback = {}) {
    const 命中定义 = this.查找运行时物品定义(itemName);
    const safeItem = { ...(命中定义?.定义 || {}), ...(sourceItem && typeof sourceItem === 'object' ? JSON.parse(JSON.stringify(sourceItem)) : {}) };
    const { 分类, 定义: definition } = this.构建交易物品定义(itemName, safeItem, { ...fallback, 分类: 命中定义?.分类 || fallback.分类 });
    const 批次列表 = this.构建交易入库批次(safeItem, qty, {
      物品名: itemName,
      分类,
      品质: safeItem.品质 || fallback.rarity,
      品质系数: safeItem.品质系数,
      阶位: safeItem.阶位,
      基础金属: safeItem.基础金属,
      魂导等级: safeItem.魂导等级,
      绑定者: safeItem.绑定者,
      有效期至tick: Number(safeItem.有效期至tick ?? fallback.expiryTick ?? 0),
      耐久: Number(safeItem.耐久 ?? safeItem.基础耐久 ?? 0),
      剩余使用次数: safeItem.剩余使用次数,
      基础耐久: safeItem.基础耐久,
      基础使用次数: safeItem.基础使用次数,
    });
    const state = 批次列表.length
      ? { 数量: 0, 批次: 批次列表 }
      : { 数量: Math.max(0, Math.floor(Number(qty || 1))) };
    return { definition, 分类, state };
  }

  buildTradeItemMetadataPatches(itemPath, currentItem = {}, nextItem = {}) {
    return [];
  }

  appendItemDefinitionPatch(patches, itemName, definition = {}, 分类 = '') {
    if (!itemName || !definition || typeof definition !== 'object') return;
    if (this.查找物品定义(itemName)) return;
    const 分类名 = this.要求物品定义分类(itemName, definition, 分类);
    patches.push({ op: 'replace', path: `/物品/${this.escapeJsonPointer(分类名)}/${this.escapeJsonPointer(itemName)}`, value: definition });
  }

  appendInventoryGainPatches(patches, charBasePath, inventory = {}, itemName = '', tradeItem = {}) {
    const current = inventory?.[itemName];
    const itemPath = `${charBasePath}/背包/${this.escapeJsonPointer(itemName)}`;
    if (current) {
      const next = this.复制JSON(current, {});
      const 追加批次 = Array.isArray(tradeItem.state?.批次) ? tradeItem.state.批次 : [];
      if (追加批次.length) {
        next.批次 = [...(Array.isArray(next.批次) ? next.批次 : []), ...追加批次.map(批次 => this.复制JSON(批次, {}))];
        if (next.数量 === undefined) next.数量 = 0;
      } else {
        next.数量 = Number(next.数量 || 0) + Number(tradeItem.state?.数量 || 1);
      }
      patches.push({ op: 'replace', path: itemPath, value: next });
    } else {
      patches.push({ op: 'replace', path: itemPath, value: tradeItem.state || { 数量: 1 } });
    }
  }

  appendInventoryConsumePatches(patches, charBasePath, inventory = {}, itemName = '', qty = 1, 批次索引 = null) {
    const current = inventory?.[itemName];
    const itemPath = `${charBasePath}/背包/${this.escapeJsonPointer(itemName)}`;
    const next = this.构建背包指定扣减值(current, qty, 批次索引);
    if (!next) patches.push({ op: 'remove', path: itemPath });
    else patches.push({ op: 'replace', path: itemPath, value: next });
  }

  escapeJsonPointer(str) {
    return String(str).replace(/~/g, '~0').replace(/\//g, '~1');
  }

  buildTradeSystemPatches(logText) {
    return [
      { op: "replace", path: `/sys/系统播报`, value: String(logText || '') }
    ];
  }

  buildTradeNarrationPrompt(logText, sections = []) {
    const safeSections = Array.isArray(sections)
      ? sections.map(section => String(section || '').trim()).filter(Boolean)
      : [];
    return [
      HIDDEN_ARBITRATION_NARRATION_RULES,
      '[前端结算已完成]',
      '本次交易涉及的货币、库存、背包与系统播报已经写入 MVU，不要重复改账、改库存，也不要再次仲裁同一笔交易。',
      String(logText || '').trim(),
      ...safeSections,
    ].filter(Boolean).join('\n\n');
  }

  normalizeSoulTowerDiscountSpiritRecord(record = {}) {
    if (!record || typeof record !== 'object' || Array.isArray(record)) return { ...SOUL_TOWER_EMPTY_DISCOUNT_SPIRIT };
    const next = { ...SOUL_TOWER_EMPTY_DISCOUNT_SPIRIT };
    next.层数 = Math.max(0, Number(record.层数 || 0) | 0);
    next.名称 = String(record.名称 || '').trim();
    next.标准物种 = String(record.标准物种 || '').trim();
    next.年限 = Math.max(0, Number(record.年限 || 0) | 0);
    next.品质 = String(record.品质 || '').trim().toUpperCase().replace('＋', '+');
    next.已使用 = record.已使用 === true;
    if (!(next.层数 > 0 && next.标准物种 && next.年限 > 0 && next.品质 && next.已使用 === false)) {
      return { ...SOUL_TOWER_EMPTY_DISCOUNT_SPIRIT };
    }
    if (!next.名称) next.名称 = `${next.标准物种}魂灵`;
    return next;
  }

  hasActiveSoulTowerDiscountSpirit(record = {}) {
    return this.normalizeSoulTowerDiscountSpiritRecord(record).层数 > 0;
  }

  getActiveSoulTowerDiscountSpirit() {
    return this.normalizeSoulTowerDiscountSpiritRecord(this.charData?.魂灵塔记录?.当前五折魂灵 || {});
  }

  canAccessSoulTowerDiscountStore(location = '', currentCity = null, worldContext = null) {
    if (!this.getWorldActionState(worldContext, { market: true }).ok) return false;
    if (/传灵塔/.test(String(location || ''))) return true;
    const stores = currentCity?.data?.商店;
    return !!stores && Object.keys(stores).some(name => /传灵塔/.test(String(name || '')));
  }

  判断传灵塔万年魂灵开放() {
    const 当前tick = Math.max(0, Math.floor(Number(this.worldData?.时间?.tick || 0)));
    if (当前tick < 传灵塔万年魂灵开放tick) return false;
    const 角色表 = this.allChars || {};
    return ['古月', '古月娜'].some(角色名 => {
      const 角色 =
        角色表[角色名] ||
        Object.values(角色表).find(候选 => {
          if (!候选 || typeof 候选 !== 'object' || Array.isArray(候选)) return false;
          return [候选.name, 候选?.base?.name, 候选?.属性?.姓名].some(名称 => String(名称 || '').trim() === 角色名);
        });
      if (!角色 || typeof 角色 !== 'object' || Array.isArray(角色)) return false;
      const 位置 = String(角色?.状态?.位置 || '').trim();
      const 势力 = 角色?.社交?.势力;
      return 位置.includes('传灵塔') && !!(势力 && typeof 势力 === 'object' && !Array.isArray(势力) && 势力['传灵塔']);
    });
  }

  getSoulTowerDiscountBasePrice(age = 0) {
    const safeAge = Math.max(0, Number(age || 0));
    if (safeAge >= 100000) return 500000000;
    if (safeAge >= 10000) return 100000000;
    if (safeAge >= 1000) return this.判断传灵塔万年魂灵开放() ? 6000000 : 20000000;
    if (safeAge >= 100) return 1000000;
    return 50000;
  }

  buildSoulTowerDiscountItemName(record = {}) {
    const normalized = this.normalizeSoulTowerDiscountSpiritRecord(record);
    if (!(normalized.层数 > 0)) return '';
    return `${normalized.标准物种}魂灵·${normalized.年限}年·${normalized.品质}`;
  }

  buildSoulTowerDiscountStoreEntry() {
    const record = this.getActiveSoulTowerDiscountSpirit();
    if (!(record.层数 > 0)) return null;
    const itemName = this.buildSoulTowerDiscountItemName(record);
    if (!itemName) return null;
    const basePrice = this.getSoulTowerDiscountBasePrice(record.年限);
    const qualityMult = Number(SOUL_TOWER_QUALITY_PRICE_MULTIPLIER[record.品质] || 1);
    const fullPrice = Math.max(1, Math.floor(basePrice * qualityMult));
    const discountPrice = Math.max(1, Math.floor(fullPrice * 0.5));
    const 经济品质 =
      record.年限 >= 100000 ? '传说' :
      record.年限 >= 10000 ? '史诗' :
      record.年限 >= 1000 ? '稀有' :
      record.年限 >= 100 ? '优秀' : '普通';
    return {
      库存: {
        [itemName]: {
          库存: 1,
          价格倍率: 0.5,
          折扣: 0,
          需求声望: 0,
          需求: {},
          _临时定义: {
            物品分类: '魂灵',
            品质: 经济品质,
            魂灵品质: record.品质,
            表象名称: record.名称,
            标准物种: record.标准物种,
            年限: record.年限,
            来源层数: record.层数,
            描述: `魂灵塔第${record.层数}层守塔魂灵特许兑换，当前为五折价格。标准物种：${record.标准物种}；年限：${record.年限}年。`,
            基础价格: fullPrice,
            默认货币: '联邦币',
          },
          _tower_discount_virtual: true,
        },
      },
    };
  }

  submitAction(playerInput, sysPrompt, requestKind, patchOps = [], transaction = {}) {
    if (this.options.onTradeAction) {
      this.options.onTradeAction({
        playerInput,
        systemPrompt: sysPrompt,
        requestKind,
        patchOps: Array.isArray(patchOps) ? patchOps : [],
        ...(transaction && typeof transaction === 'object' ? transaction : {}),
      });
    }
  }

  // --- 商店采购模块 ---
  populateShopData() {
    const storeSel = this.$('#shop-store-sel');
    storeSel.innerHTML = '';
    if (Object.keys(this.currentStores).length === 0) {
      storeSel.innerHTML = '<option value="">[当前区域无商店]</option>';
      this.updateShopItems();
      return;
    }
    for (const sName in this.currentStores) {
      const opt = document.createElement('option');
      opt.value = sName;
      opt.textContent = sName;
      storeSel.appendChild(opt);
    }
    this.updateShopItems();
  }

  updateShopItems() {
    const storeName = this.$('#shop-store-sel').value;
    const itemSel = this.$('#shop-item-sel');
    itemSel.innerHTML = '';

    if (!storeName || !this.currentStores[storeName] || !this.currentStores[storeName].库存) {
      itemSel.innerHTML = '<option value="">[该商店无货]</option>';
      this.updateShopPreview();
      return;
    }

    const inv = this.currentStores[storeName].库存;
    let hasItem = false;
    for (const iName in inv) {
      if (Number(inv[iName].库存 || 0) > 0) {
        const opt = document.createElement('option');
        opt.value = iName;
        opt.textContent = `${iName} (库存: ${Number(inv[iName].库存 || 0)})`;
        itemSel.appendChild(opt);
        hasItem = true;
      }
    }
    if (!hasItem) itemSel.innerHTML = '<option value="">[商品已售罄]</option>';
    this.updateShopPreview();
  }

  updateShopPreview() {
    const storeName = this.$('#shop-store-sel').value;
    const itemName = this.$('#shop-item-sel').value;
    const qty = parseInt(this.$('#shop-qty').value) || 1;
    const btn = this.$('#btn-buy');

    if (!storeName || !itemName || !this.currentStores[storeName]?.库存?.[itemName]) {
      this.$('#shop-base-price').textContent = '-';
      this.$('#shop-price').textContent = '-';
      this.$('#shop-market').textContent = '-';
      this.$('#shop-total').textContent = '-';
      this.$('#shop-fame').textContent = '-';
      this.$('#shop-stock').textContent = '-';
      btn.disabled = true;
      this.updateTradeMetaPanel('shop', null);
      return;
    }

    const item = this.currentStores[storeName].库存[itemName];
    const storeData = this.currentStores[storeName] || {};
    const worldAction = this.getConfiguredTradeWorldAction('trade_buy');
    const worldContext = this.resolveWorldActionContext(worldAction.actionType, this.charData?.状态?.位置 || '');
    const worldActionState = this.getWorldActionState(worldContext, { market: true, marketFunction: worldAction.marketFunction, storeName });
    const 商店营业中 = worldActionState.ok;
    const isSoulTowerDiscountTrade = item && item._tower_discount_virtual === true;
    const itemDefinition = item._临时定义 || this.取物品定义(itemName);
    const priceSource = { ...(itemDefinition || {}), ...(item && typeof item === 'object' ? item : {}) };
    const priceMultiplier = Number(item.价格倍率 || 1);
    const discount = Number(item.折扣 || 0);
    const 批次倍率 = this.计算来源批次平均倍率(item, qty, itemDefinition);
    const itemBasePrice = this.读取交易物品基础价格(itemName, priceSource, {}, itemDefinition?.分类 || '剧情杂物');
    const baseUnitPrice = Math.max(0, Math.floor(itemBasePrice * 批次倍率 * priceMultiplier * Math.max(0, 1 - discount)));
    const unitPrice = this.getMarketAdjustedPrice(baseUnitPrice, 'buy', { fixed: isSoulTowerDiscountTrade, context: worldContext });
    const privilegeDiscount = this.resolvePrivilegePurchaseDiscount(storeName, itemName, itemDefinition);
    const total = Math.max(0, Math.floor(unitPrice * privilegeDiscount.支付比例 / 100)) * qty;
    const userFame = Number(this.charData?.社交?.声望 || 0);
    const currency = this.resolveTradeCurrency(item, storeName, this.charData?.状态?.位置 || '', storeData);
    const userCoin = Number(this.charData?.财富?.[currency] || 0);

    this.$('#shop-base-price').textContent = `${baseUnitPrice.toLocaleString()} ${this.getCurrencyLabel(currency)}`;
    this.$('#shop-price').textContent = `${unitPrice.toLocaleString()} ${this.getCurrencyLabel(currency)}`;
    this.$('#shop-market').textContent = 商店营业中
      ? `${this.getMarketAdjustmentText('buy', { fixed: isSoulTowerDiscountTrade, context: worldContext })}${privilegeDiscount.支付比例 < 100 ? ' · 权限优惠' : ''}`
      : worldActionState.reason || this.getShopOpenStateText(worldContext, storeName);

    const totalEl = this.$('#shop-total');
    totalEl.textContent = `${total.toLocaleString()} ${this.getCurrencyLabel(currency)}`;
    totalEl.className = (userCoin >= total) ? "val-highlight" : "val-warn";

    const fameEl = this.$('#shop-fame');
    fameEl.textContent = Number(item.需求声望 || 0);
    fameEl.className = (userFame >= Number(item.需求声望 || 0)) ? "val-highlight" : "val-warn";

    const stockEl = this.$('#shop-stock');
    stockEl.textContent = Number(item.库存 || 0);
    stockEl.className = (Number(item.库存 || 0) >= qty) ? "val-highlight" : "val-warn";

    this.updateTradeMetaPanel('shop', this.resolveTradeItemInfo(itemName, item, { source: storeName, desc: 商店营业中 ? (this.取物品定义(itemName)?.描述 || `可在 ${storeName} 购得`) : `${storeName} 当前不可交易。` }));

    if (itemBasePrice <= 0) {
      this.$('#shop-base-price').textContent = '未知/禁售';
      this.$('#shop-market').textContent = '-';
      this.$('#shop-price').textContent = '-';
      this.$('#shop-total').textContent = '无法交易';
      this.$('#shop-total').className = 'val-warn';
      btn.disabled = true;
      return;
    }

    if (!商店营业中) {
      btn.disabled = true;
      return;
    }

    if (!this.isCurrencySpendable(currency)) {
      totalEl.className = "val-warn";
      totalEl.textContent = this.getCurrencyBlockedMessage(currency);
      btn.disabled = true;
      return;
    }

    btn.disabled = (!worldActionState.ok || userCoin < total || userFame < Number(item.需求声望 || 0) || Number(item.库存 || 0) < qty);
  }

  executeShopBuy() {
    const storeName = this.$('#shop-store-sel').value;
    const itemName = this.$('#shop-item-sel').value;
    const qty = parseInt(this.$('#shop-qty').value) || 1;
    const item = this.currentStores?.[storeName]?.库存?.[itemName];
    if (!item) return this.显示提示('当前没有可交易的商品。');
    const loc = this.charData?.状态?.位置 || '';
    const worldAction = this.getConfiguredTradeWorldAction('trade_buy');
    const worldContext = this.resolveWorldActionContext(worldAction.actionType, loc);
    const worldActionState = this.getWorldActionState(worldContext, { market: true, marketFunction: worldAction.marketFunction, storeName });
    if (!worldActionState.ok) return this.显示提示(worldActionState.reason);
    const storeData = this.currentStores[storeName] || {};
    const currency = this.resolveTradeCurrency(item, storeName, this.charData?.状态?.位置 || '', storeData);
    const isSoulTowerDiscountTrade = item && item._tower_discount_virtual === true;
    const itemDefinition = item._临时定义 || this.取物品定义(itemName);
    const priceSource = { ...(itemDefinition || {}), ...(item && typeof item === 'object' ? item : {}) };
    const 批次倍率 = this.计算来源批次平均倍率(item, qty, itemDefinition);
    const itemBasePrice = this.读取交易物品基础价格(itemName, priceSource, {}, itemDefinition?.分类 || '剧情杂物');
    if (itemBasePrice <= 0) return this.显示提示('该商品没有有效价格，当前不可交易。');
    const baseUnitPrice = Math.max(0, Math.floor(itemBasePrice * 批次倍率 * Number(item.价格倍率 || 1) * Math.max(0, 1 - Number(item.折扣 || 0))));
    const privilegeDiscount = this.resolvePrivilegePurchaseDiscount(storeName, itemName, itemDefinition);
    const total = Math.max(
      0,
      Math.floor(this.getMarketAdjustedPrice(baseUnitPrice, 'buy', { fixed: isSoulTowerDiscountTrade, context: worldContext }) * privilegeDiscount.支付比例 / 100),
    ) * qty;

    if (!this.isCurrencySpendable(currency)) return this.显示提示(this.getCurrencyBlockedMessage(currency));

    let patchOps = [];
    let newWealth = (this.charData.财富?.[currency] || 0) - total;
    patchOps.push({ op: "replace", path: `${this.activeCharBasePath}/财富/${this.escapeJsonPointer(currency)}`, value: newWealth });
    if (!isSoulTowerDiscountTrade) {
      patchOps.push({ op: "replace", path: `/world/地点/${this.escapeJsonPointer(loc)}/商店/${this.escapeJsonPointer(storeName)}/库存/${this.escapeJsonPointer(itemName)}/库存`, value: Number(item.库存 || 0) - qty });
    }

    const 采购定义 = { ...(item._临时定义 || this.取物品定义(itemName)), ...(item || {}) };
    const tradeItem = this.buildInventoryItemFromTradeSource(itemName, 采购定义, qty, { source: storeName, desc: 采购定义?.描述 || `购自${storeName}`, currency });
    this.appendItemDefinitionPatch(patchOps, itemName, tradeItem.definition, tradeItem.分类);
    this.appendInventoryGainPatches(patchOps, this.activeCharBasePath, this.charData.背包 || {}, itemName, tradeItem);
    if (isSoulTowerDiscountTrade) {
      patchOps.push({
        op: "replace",
        path: `${this.activeCharBasePath}/魂灵塔记录/当前五折魂灵`,
        value: { ...SOUL_TOWER_EMPTY_DISCOUNT_SPIRIT },
      });
    }

    const log = isSoulTowerDiscountTrade
      ? `[魂灵塔兑换][兑换热][交易触发待处理] ${this.activeName} 在${storeName}以五折价格兑换了【${itemName}】。`
      : `[交易成功][买入热][交易触发待处理] ${this.activeName} 在${storeName} 花费 ${total} ${this.getCurrencyLabel(currency)} 购买了 ${qty} 份【${itemName}】。`;
    patchOps.push(...this.buildTradeSystemPatches(log));

    const sysPrompt = this.buildTradeNarrationPrompt(log, [
      `[交易地点]\n${storeName}`,
      `[交易类型]\n商店购买`,
      `[市场调整]\n${this.getMarketAdjustmentText('buy', { fixed: isSoulTowerDiscountTrade, context: worldContext })}`,
      ...(privilegeDiscount.支付比例 < 100 ? [`[特殊权限]\n${privilegeDiscount.记录?.名称 || '折扣权限'}已生效。`] : []),
      `[结算摘要]\n已支付 ${total} ${this.getCurrencyLabel(currency)}；已获得 ${qty} 份【${itemName}】。`,
    ]);

    this.submitAction(
      `我要在【${storeName}】购买 ${qty} 份【${itemName}】。`,
      sysPrompt,
      'trade_shop_buy',
      patchOps,
      {
        privilegeID: privilegeDiscount.权限ID || '',
        privilegeCost: privilegeDiscount.权限ID ? 1 : 0,
        交易参数: {
          角色名: this.activeName,
          地点: loc,
          商店: storeName,
          物品: itemName,
          数量: qty,
          货币: currency,
          预期总价: total,
          魂灵塔兑换: isSoulTowerDiscountTrade,
        },
      },
    );
  }

  resolvePrivilegePurchaseDiscount(storeName = '', itemName = '', itemDefinition = {}) {
    let runtime = window.__LWCS_COMPETITION_PRIVILEGE_RUNTIME__;
    try {
      if (!runtime && window.parent && window.parent !== window) runtime = window.parent.__LWCS_COMPETITION_PRIVILEGE_RUNTIME__;
    } catch (错误) {}
    if (!runtime || typeof runtime.计算购买支付比例 !== 'function') return { 权限ID: '', 记录: null, 支付比例: 100 };
    const rootData = this.rootData || {};
    const itemCategory = this.查找运行时物品定义(itemName)?.分类 || itemDefinition?.分类 || '';
    return runtime.计算购买支付比例(rootData, this.activeName, {
      地点: this.charData?.状态?.位置 || '',
      商店: storeName,
      物品分类: itemCategory,
      物品: itemName,
    });
  }

  // --- 资产出售模块 ---
  populateSellData() {
    const invSel = this.$('#sell-item-sel');
    invSel.innerHTML = '';
    let hasItem = false;
    for (const iName in (this.charData?.背包 || {})) {
      const item = this.charData.背包[iName];
      const 普通数量 = this.读取背包普通数量(item);
      if (普通数量 > 0) {
        const opt = document.createElement('option');
        opt.value = this.编码出售引用(iName, -1);
        opt.textContent = `${iName} (剩${普通数量})`;
        invSel.appendChild(opt);
        hasItem = true;
      }
      this.读取背包批次列表(item).forEach(({ 批次, 索引 }) => {
        const 数量 = Math.max(0, Math.floor(Number(批次.数量 || 0)));
        const 明细 = [];
        if (批次.品质) 明细.push(批次.品质);
        if (批次.品质系数 !== undefined) 明细.push(`Q${Number(批次.品质系数 || 1).toFixed(2)}`);
        const 融合率 = 批次?.副职业参数?.融合参数?.融合率;
        if (融合率 !== undefined) 明细.push(`融合${融合率}%`);
        if (批次.耐久 !== undefined) 明细.push(`耐久${批次.耐久}`);
        const opt = document.createElement('option');
        opt.value = this.编码出售引用(iName, 索引);
        opt.textContent = `${iName} · 批次${索引 + 1} (${明细.concat(`剩${数量}`).join(' / ')})`;
        invSel.appendChild(opt);
        hasItem = true;
      });
    }
    if (!hasItem) invSel.innerHTML = '<option value="">[背包空空如也]</option>';
    this.updateSellPreview();
  }

  updateSellPreview() {
    const 出售引用 = this.$('#sell-item-sel').value;
    const qty = parseInt(this.$('#sell-qty').value) || 1;
    const btn = this.$('#btn-sell');
    const 出售项 = this.读取出售引用上下文(出售引用, qty);

    if (!出售项 || !出售项.物品名 || 出售项.可用数量 <= 0) {
      this.$('#sell-base-price').textContent = '-';
      this.$('#sell-market').textContent = '-';
      this.$('#sell-price').textContent = '-';
      this.$('#sell-total').textContent = '-';
      btn.disabled = true;
      this.updateTradeMetaPanel('sell', null);
      return;
    }

    const itemName = 出售项.物品名;
    const loc = this.charData?.状态?.位置 || '';
    const worldAction = this.getConfiguredTradeWorldAction('trade_sell');
    const worldContext = this.resolveWorldActionContext(worldAction.actionType, loc);
    const worldActionState = this.getWorldActionState(worldContext, { market: true, marketFunction: worldAction.marketFunction });
    const currency = this.resolveTradeCurrency(出售项.展示物品, '', loc);
    const 系统禁售 = 系统禁售物品分类集合.has(出售项.分类 || '') || /兑换凭证|兑换券/.test(itemName);
    const basePrice = Math.max(0, Math.floor(this.estimateBasePrice(itemName, 出售项.分类 || '物品') * this.计算来源批次平均倍率(出售项.来源状态 || {}, qty, 出售项.展示物品 || this.取物品定义(itemName))));
    const baseSellPrice = Math.floor(basePrice * 0.5);
    const sellPrice = this.getMarketAdjustedPrice(baseSellPrice, 'sell', { context: worldContext });
    const total = sellPrice * qty;

    this.updateTradeMetaPanel('sell', this.resolveTradeItemInfo(itemName, 出售项.展示物品, { source: 出售项.展示物品?.来源 || 出售项.展示物品?.绑定者 || '背包持有' }));

    if (系统禁售 || basePrice === 0 || !this.isCurrencySpendable(currency) || !worldActionState.ok) {
      this.$('#sell-base-price').textContent = "禁售物品";
      this.$('#sell-market').textContent = worldActionState.ok ? '-' : worldActionState.reason;
      this.$('#sell-price').textContent = '-';
      this.$('#sell-total').textContent = "无法交易";
      btn.disabled = true;
    } else {
      this.$('#sell-base-price').textContent = `${baseSellPrice.toLocaleString()} ${this.getCurrencyLabel(currency)}`;
      this.$('#sell-market').textContent = this.getMarketAdjustmentText('sell', { context: worldContext });
      this.$('#sell-price').textContent = `${sellPrice.toLocaleString()} ${this.getCurrencyLabel(currency)}`;
      this.$('#sell-total').textContent = `${total.toLocaleString()} ${this.getCurrencyLabel(currency)}`;
      btn.disabled = 出售项.可用数量 < qty;
    }
  }

  executeSell() {
    const 出售引用 = this.$('#sell-item-sel').value;
    const qty = parseInt(this.$('#sell-qty').value) || 1;
    const 出售项 = this.读取出售引用上下文(出售引用, qty);
    if (!出售项 || !出售项.物品名 || 出售项.可用数量 < qty) return this.显示提示('背包数量不足。');
    const itemName = 出售项.物品名;
    const loc = this.charData?.状态?.位置 || '';
    const worldAction = this.getConfiguredTradeWorldAction('trade_sell');
    const worldContext = this.resolveWorldActionContext(worldAction.actionType, loc);
    const worldActionState = this.getWorldActionState(worldContext, { market: true, marketFunction: worldAction.marketFunction });
    if (!worldActionState.ok) return this.显示提示(worldActionState.reason);
    const currency = this.resolveTradeCurrency(出售项.展示物品, '', loc);
    if (系统禁售物品分类集合.has(出售项.分类 || '') || /兑换凭证|兑换券/.test(itemName)) return this.显示提示('凭证类物品不能出售。');
    if (!this.isCurrencySpendable(currency)) return this.显示提示(this.getCurrencyBlockedMessage(currency));
    const basePrice = Math.max(0, Math.floor(this.estimateBasePrice(itemName, 出售项.分类 || '物品') * this.计算来源批次平均倍率(出售项.来源状态 || {}, qty, 出售项.展示物品 || this.取物品定义(itemName))));
    if (basePrice <= 0) return this.显示提示('该物品当前无法出售。');
    const totalEarn = this.getMarketAdjustedPrice(Math.floor(basePrice * 0.5), 'sell', { context: worldContext }) * qty;

    let patchOps = [];
    this.appendInventoryConsumePatches(patchOps, this.activeCharBasePath, this.charData.背包 || {}, itemName, qty, 出售项.批次索引);
    patchOps.push({ op: "replace", path: `${this.activeCharBasePath}/财富/${this.escapeJsonPointer(currency)}`, value: (this.charData.财富?.[currency] || 0) + totalEarn });

    const log = `[交易成功][卖出热][交易触发待处理] ${this.activeName} 向系统商店出售了 ${qty} 份【${itemName}】，获得 ${totalEarn} ${this.getCurrencyLabel(currency)}。`;
    patchOps.push(...this.buildTradeSystemPatches(log));

    const sysPrompt = this.buildTradeNarrationPrompt(log, [
      `[交易类型]\n系统出售`,
      `[市场调整]\n${this.getMarketAdjustmentText('sell', { context: worldContext })}`,
      `[结算摘要]\n已卖出 ${qty} 份【${itemName}】；已获得 ${totalEarn} ${this.getCurrencyLabel(currency)}。`,
    ]);

    this.submitAction(`我要卖出 ${qty} 份【${itemName}】换钱。`, sysPrompt, 'trade_system_sell', patchOps);
  }

  // --- 私下交易模块 ---
  updatePrivPreview() {
    const action = this.$('#priv-action').value;
    const itemName = this.$('#priv-item').value;
    const qty = parseInt(this.$('#priv-qty').value) || 1;
    const price = parseInt(this.$('#priv-price').value) || 1;
    const btn = this.$('#btn-private');
    const targetNpc = String(this.$('#priv-npc').value || '').trim();
    const total = price * qty;
    const attEl = this.$('#priv-attitude');

    const ctx = this.getPrivateTradeContext(action, targetNpc, itemName, qty, price);

    const currencyLabel = this.getCurrencyLabel(ctx.currency || this.getDefaultCurrencyByContext('', this.charData?.状态?.位置 || ''));
    this.$('#priv-base-price').textContent = ctx.marketPrice > 0 ? `${ctx.marketPrice.toLocaleString()} ${currencyLabel}` : (ctx.basePrice > 0 ? `${ctx.basePrice.toLocaleString()} ${currencyLabel}` : '未知/禁售');
    this.$('#priv-market').textContent = ctx.basePrice > 0 ? this.getMarketAdjustmentText(action === '私下买入' ? 'buy' : 'sell', { context: ctx.worldContext }) : '-';
    this.$('#priv-total').textContent = `${total.toLocaleString()} ${currencyLabel}`;

    const previewItem = action === '私下买入' ? ctx.npcItem : ctx.playerItem;
    this.updateTradeMetaPanel('priv', previewItem ? this.resolveTradeItemInfo(itemName, previewItem, { source: action === '私下买入' ? ctx.counterparty : this.activeName }) : null);

    btn.disabled = false;
    attEl.className = "";

    if (ctx.error) {
      attEl.textContent = ctx.error;
      attEl.className = "val-warn";
      btn.disabled = true;
      return;
    }

    attEl.textContent = `${action === "私下买入" ? '可尝试成交' : '可尝试出手'} · ${ctx.note}`;
    attEl.className = ctx.successRate >= 60 ? "val-highlight" : "val-warn";
  }

  executePrivateTrade() {
    const action = this.$('#priv-action').value;
    const targetNpc = String(this.$('#priv-npc').value || '').trim();
    const itemName = this.$('#priv-item').value;
    const qty = parseInt(this.$('#priv-qty').value) || 1;
    const price = parseInt(this.$('#priv-price').value) || 1;
    const ctx = this.getPrivateTradeContext(action, targetNpc, itemName, qty, price);
    if (ctx.error) return this.显示提示(ctx.error);
    const counterparty = ctx.counterparty || targetNpc;

    let patchOps = [];
    let log = "";
    const roll = Math.floor(Math.random() * 100) + 1;
    const isSuccess = roll <= ctx.successRate;

    if (action === "私下买入") {
      if (!isSuccess) {
        log = `[私下交易失败] ${this.activeName} 向 ${counterparty} 报价 ${price} ${this.getCurrencyLabel(ctx.currency)}，但对方没有接受。`;
      } else {
        patchOps.push({ op: "replace", path: `${this.activeCharBasePath}/财富/${this.escapeJsonPointer(ctx.currency)}`, value: (this.charData.财富?.[ctx.currency] || 0) - ctx.total });
        const tradeItem = this.buildInventoryItemFromTradeSource(itemName, ctx.npcItem, qty, { source: counterparty, desc: `从 ${counterparty} 处私下购得` });
        this.appendItemDefinitionPatch(patchOps, itemName, tradeItem.definition, tradeItem.分类);
        this.appendInventoryGainPatches(patchOps, this.activeCharBasePath, this.charData.背包 || {}, itemName, tradeItem);
        if (ctx.usesMarketStore) {
          patchOps.push({
            op: "replace",
            path: `/world/地点/${this.escapeJsonPointer(ctx.locationKey)}/商店/${this.escapeJsonPointer(ctx.storeName)}/库存/${this.escapeJsonPointer(itemName)}/库存`,
            value: Number(ctx.npcItem?.库存 || 0) - qty,
          });
        } else {
          this.appendInventoryConsumePatches(patchOps, `/char/${this.escapeJsonPointer(targetNpc)}`, ctx.targetChar?.背包 || {}, itemName, qty);
          patchOps.push({ op: "replace", path: `/char/${this.escapeJsonPointer(targetNpc)}/财富/${this.escapeJsonPointer(ctx.currency)}`, value: (ctx.targetChar?.财富?.[ctx.currency] || 0) + ctx.total });
        }
        log = `[私下交易成功][买入热][交易触发待处理] ${this.activeName} 以总价 ${ctx.total} ${this.getCurrencyLabel(ctx.currency)}从 ${counterparty} 处买入了 ${qty} 份【${itemName}】。`;
      }
    } else {
      if (!isSuccess) {
        log = `[私下交易失败] ${this.activeName} 向 ${counterparty} 报价 ${price} ${this.getCurrencyLabel(ctx.currency)}，但对方没有接手。`;
      } else {
        this.appendInventoryConsumePatches(patchOps, this.activeCharBasePath, this.charData.背包 || {}, itemName, qty);
        patchOps.push({ op: "replace", path: `${this.activeCharBasePath}/财富/${this.escapeJsonPointer(ctx.currency)}`, value: (this.charData.财富?.[ctx.currency] || 0) + ctx.total });
        if (ctx.usesMarketStore) {
          const stockPath = `/world/地点/${this.escapeJsonPointer(ctx.locationKey)}/商店/${this.escapeJsonPointer(ctx.storeName)}/库存/${this.escapeJsonPointer(itemName)}`;
          const existingStock = ctx.storeData?.库存?.[itemName];
          patchOps.push(existingStock
            ? { op: "replace", path: `${stockPath}/库存`, value: Number(existingStock.库存 || 0) + qty }
            : { op: "add", path: stockPath, value: { 库存: qty, 价格倍率: 1, 折扣: 0, 需求声望: 0, 需求: {}, 批次: [] } });
        } else {
          const npcItem = this.buildInventoryItemFromTradeSource(itemName, this.charData.背包[itemName], qty, { source: this.activeName, desc: `从 ${this.activeName} 处私下收购` });
          this.appendItemDefinitionPatch(patchOps, itemName, npcItem.definition, npcItem.分类);
          this.appendInventoryGainPatches(patchOps, `/char/${this.escapeJsonPointer(targetNpc)}`, ctx.targetChar?.背包 || {}, itemName, npcItem);
          patchOps.push({ op: "replace", path: `/char/${this.escapeJsonPointer(targetNpc)}/财富/${this.escapeJsonPointer(ctx.currency)}`, value: (ctx.targetChar?.财富?.[ctx.currency] || 0) - ctx.total });
        }
        log = `[私下交易成功][卖出热][交易触发待处理] ${this.activeName} 以单价 ${price} ${this.getCurrencyLabel(ctx.currency)}向 ${counterparty} 卖出 ${qty} 份【${itemName}】，获得 ${ctx.total} ${this.getCurrencyLabel(ctx.currency)}。`;
      }
    }

    patchOps.push(...this.buildTradeSystemPatches(log));

    const sysPrompt = this.buildTradeNarrationPrompt(log, [
      `[交易对象]\n${counterparty}`,
      `[交易类型]\n${ctx.isBlackMarket ? `${action}（黑市渠道）` : action}`,
      `[市场调整]\n${this.getMarketAdjustmentText(action === '私下买入' ? 'buy' : 'sell', { context: ctx.worldContext })}`,
      `[结算摘要]\n${isSuccess ? `本次成交 ${qty} 份【${itemName}】，总价 ${ctx.total} ${this.getCurrencyLabel(ctx.currency)}。` : `本次未成交，报价为单价 ${price} ${this.getCurrencyLabel(ctx.currency)}。`}`
    ]);

    this.submitAction(`我要和【${counterparty}】${action} ${qty} 份【${itemName}】，单价 ${price} ${this.getCurrencyLabel(ctx.currency)}。`, sysPrompt, 'trade_private', patchOps);
  }

  // --- 拍卖行模块 ---
  populateAuctionData() {
    const sel = this.$('#auc-item-sel');
    sel.innerHTML = '';
    if (this.currentAuction.状态 === "休市" || !this.currentAuction.拍品 || Object.keys(this.currentAuction.拍品).length === 0) {
      sel.innerHTML = '<option value="">[拍卖行休市或无拍品]</option>';
      this.updateAucPreview();
      return;
    }
    if (!this.当前地点可参与本期拍卖()) {
      sel.innerHTML = '<option value="">[当前地点无可参与拍品]</option>';
      this.updateAucPreview();
      return;
    }
    for (const iName in this.currentAuction.拍品) {
      const opt = document.createElement('option');
      opt.value = iName;
      opt.textContent = iName;
      sel.appendChild(opt);
    }
    this.updateAucPreview();
  }

  updateAucPreview() {
    const itemName = this.$('#auc-item-sel').value;
    const bid = parseInt(this.$('#auc-bid').value) || 0;
    const btn = this.$('#btn-auc');

    if (!this.当前地点可参与本期拍卖()) {
      this.$('#auc-current-price').textContent = '-';
      this.$('#auc-desc').textContent = '-';
      btn.disabled = true;
      return;
    }

    if (!itemName || !this.currentAuction.拍品?.[itemName]) {
      this.$('#auc-current-price').textContent = '-';
      this.$('#auc-desc').textContent = '-';
      btn.disabled = true;
      return;
    }

    const item = this.currentAuction.拍品[itemName];
    const currency = this.resolveTradeCurrency(item, '拍卖行', this.charData?.状态?.位置 || '', this.currentAuction || {});
    const itemDefinition = this.取物品定义(itemName) || item || {};
    const currentPrice = 读取显式交易物品价格(item) ?? 读取显式交易物品价格(itemDefinition) ?? 0;
    if (currentPrice <= 0) {
      this.$('#auc-current-price').textContent = '未知/禁售';
      this.$('#auc-desc').textContent = `[${itemDefinition.品质 || item.品级 || '普通'}] ${itemDefinition.描述 || item.背景 || item.描述 || '暂无说明'}`;
      btn.disabled = true;
      return;
    }
    this.$('#auc-current-price').textContent = `${currentPrice.toLocaleString()} ${this.getCurrencyLabel(currency)}`;
    this.$('#auc-desc').textContent = `[${itemDefinition.品质 || item.品级 || '普通'}] ${itemDefinition.描述 || item.背景 || item.描述 || '暂无说明'}`;

    const userCoin = this.charData?.财富?.[currency] || 0;
    if (!this.isCurrencySpendable(currency)) {
      btn.disabled = true;
      return;
    }
    btn.disabled = (bid <= currentPrice || userCoin < bid);
  }

  executeAuction() {
    if (!this.当前地点可参与本期拍卖()) return this.显示提示('当前地点没有可参与的拍卖。');
    const itemName = this.$('#auc-item-sel').value;
    const bid = parseInt(this.$('#auc-bid').value) || 0;
    const item = this.currentAuction.拍品[itemName];
    const worldContext = this.resolveWorldActionContext('trade_auction', this.charData?.状态?.位置 || '');
    const worldActionState = this.getWorldActionState(worldContext, { market: true, marketFunction: '拍卖' });
    if (!worldActionState.ok) return this.显示提示(worldActionState.reason);
    const currency = this.resolveTradeCurrency(item, '拍卖行', this.charData?.状态?.位置 || '', this.currentAuction || {});
    const itemDefinition = this.取物品定义(itemName) || item || {};
    const currentPrice = 读取显式交易物品价格(item) ?? 读取显式交易物品价格(itemDefinition) ?? 0;
    if (currentPrice <= 0) return this.显示提示('该拍品没有有效价格，当前不可竞拍。');

    if (!this.isCurrencySpendable(currency)) return this.显示提示(this.getCurrencyBlockedMessage(currency));

    let patchOps = [];
    patchOps.push({ op: "replace", path: `${this.activeCharBasePath}/财富/${this.escapeJsonPointer(currency)}`, value: (this.charData.财富?.[currency] || 0) - bid });

    const tradeItem = this.buildInventoryItemFromTradeSource(itemName, item, 1, { source: '拍卖行', rarity: item.品级 || '普通', desc: item.背景 || item.描述 || '拍卖所得', currency });
    this.appendItemDefinitionPatch(patchOps, itemName, tradeItem.definition, tradeItem.分类);
    this.appendInventoryGainPatches(patchOps, this.activeCharBasePath, this.charData.背包 || {}, itemName, tradeItem);
    patchOps.push({ op: "remove", path: `/world/拍卖/拍品/${this.escapeJsonPointer(itemName)}` });
    const log = `[竞拍成功][竞拍热][交易触发待处理] ${this.activeName} 豪掷 ${bid} ${this.getCurrencyLabel(currency)} 拍下了【${itemName}】。`;
    patchOps.push(...this.buildTradeSystemPatches(log));

    const sysPrompt = this.buildTradeNarrationPrompt(log, [
      `[交易地点]\n拍卖行`,
      `[交易类型]\n竞拍成交`,
      `[结算摘要]\n已支付 ${bid} ${this.getCurrencyLabel(currency)}；已拍得【${itemName}】。`,
    ]);

    this.submitAction(
      `【举牌竞拍】我出价 ${bid} 竞拍【${itemName}】！`,
      sysPrompt,
      'trade_auction',
      patchOps,
      {
        privilegeCost: 0,
          交易参数: {
            角色名: this.activeName,
            地点: this.charData?.状态?.位置 || '',
            物品: itemName,
            出价: bid,
            货币: currency,
          },
      },
    );
  }

}

// 向全局挂载
window.mountTradeUI = function(containerElement, snapshot, options = {}) {
  return new TradeUIComponent(containerElement, snapshot, options);
};

window.__LWCS_RESOLVE_TRADE_ITEM_PRICE__ = function(snapshot, 物品名, 选项 = {}) {
  const 组件 = Object.create(TradeUIComponent.prototype);
  组件.snapshot = snapshot || {};
  组件.options = {};
  return 组件.解析交易物品价格(物品名, 选项);
};

;
