        if (field === '防御穿透') return { amount: normZero(n), unit: 'PERCENT', pending: null };
        if (m[1] === '') return { pending: 'PENDING_DIRECTION_PROJECTION' };
        return { amount: normZero(m[1] === '-' ? -n : n), unit: 'PERCENT', pending: null };
