        featureId: (sel || alt).featureId,
        featureCode: code,
        tacticalConcept: (sel || alt).tacticalConcept,
        deltaContribution: selContrib - altContrib,
        zeroByMask: zeroByMask,
        statusOfSelected: statusOf(sel),
        statusOfAlternative: statusOf(alt),
