        if (!skill) return [];
        const effects = Array.isArray(skill?._效果数组) ? skill._效果数组 : [];
        const triggered = effects.filter(effect => ['战斗开始', '回合开始', '受击前', '受击后', '濒死时', '被控制时', '命中后']
          .includes(String(effect?.触发方式 || skill?.触发方式 || '').trim()));
