    if (reportAudit?.passed !== true || Number(reportAudit?.fatalCount || 0) > 0) {
      throw new Error('battle_result_report_audit_failed');
    }
    const reportDto = reportAudit?.reportDto && typeof reportAudit.reportDto === 'object'
