            logDebug_ACU(bestSource
                ? '[交火模式配置] 已从旧 profile/角色配置迁移到全局 globalMeta.vectorMemoryConfigGlobal'
                : '[交火模式配置] 已初始化全局 globalMeta.vectorMemoryConfigGlobal');
